    /// A sealed workspace state must restore byte-exactly onto the base it was
    /// sealed against, including content no language adapter understands.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_stash_seals_restores_and_round_trips_exact_workspace_state() {
        let (state, _layout, repository, main_change, _feature) =
            universal_branch_test_state("stash-round-trip");

        let base_compose = std::fs::read(repository.join("selected/compose.yaml")).unwrap();
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: dirty\n",
        )
        .unwrap();
        std::fs::write(
            repository.join("selected/scratch.mystery"),
            [0x00_u8, 0xfe, 0x7f, 0x41],
        )
        .unwrap();
        let dirty_compose = std::fs::read(repository.join("selected/compose.yaml")).unwrap();
        let dirty_scratch = std::fs::read(repository.join("selected/scratch.mystery")).unwrap();
        assert_ne!(dirty_compose, base_compose);

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let sealed: kin_cli::commands::stash::StashResponse =
            serde_json::from_slice(&body).unwrap();
        let entry = sealed.entry.expect("seal reports the sealed stash");
        assert_eq!(entry.ordinal, 0);
        assert_eq!(
            entry.name,
            kin_model::RefName::from_utf8("refs/kin/stash/0").unwrap()
        );
        assert_eq!(
            entry.base_target,
            Some(kin_model::RefTarget::change(main_change)),
            "a sealed state names the exact authority target it was taken against"
        );

        assert_eq!(
            std::fs::read(repository.join("selected/compose.yaml")).unwrap(),
            base_compose,
            "sealing with a reset returns tracked bytes to their authority base"
        );
        assert!(
            !repository.join("selected/scratch.mystery").exists(),
            "sealing with a reset removes members the base tree does not hold"
        );
        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let workspace = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap()
            .clone();
        assert!(
            !workspace.is_dirty(),
            "the workspace is clean in graph-owned authority after a reset seal"
        );
        assert!(
            !lease
                .metadata()
                .ref_state
                .refs
                .iter()
                .any(|repository_ref| repository_ref.name.is_branch()
                    && repository_ref.name == entry.name),
            "a stash is never published as a branch"
        );
        drop(lease);
        drop(authority);

        let listed = stash_entries(Arc::clone(&state)).await;
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].change_id, entry.change_id);

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_pop()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        assert_eq!(
            std::fs::read(repository.join("selected/compose.yaml")).unwrap(),
            dirty_compose,
            "restore reproduces the sealed bytes exactly"
        );
        assert_eq!(
            std::fs::read(repository.join("selected/scratch.mystery")).unwrap(),
            dirty_scratch,
            "restore reproduces sealed content no adapter understands"
        );
        assert!(
            stash_entries(Arc::clone(&state)).await.is_empty(),
            "a restored stash is dropped in the same transaction that restored it"
        );
        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let workspace = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap()
            .clone();
        assert!(
            workspace.is_dirty(),
            "restore returns the workspace to the dirty state that was sealed"
        );
        assert_eq!(workspace.tree_hash, entry.tree_hash);
    }

    /// Install one entity into the daemon query graph alone, the way the
    /// asynchronous LSP enrichment worker and parser reconciliation both do:
    /// derived semantics that have not crossed the repository compare-and-swap.
    #[cfg(unix)]
    fn install_unpublished_derived_entity(state: &DaemonState, name: &str) -> kin_model::EntityId {
        let entity = kin_model::Entity {
            id: kin_model::EntityId::new(),
            kind: kin_model::EntityKind::Function,
            name: name.to_string(),
            language: kin_model::LanguageId::Rust,
            fingerprint: kin_model::SemanticFingerprint {
                algorithm: kin_model::FingerprintAlgorithm::V1TreeSitter,
                ast_hash: kin_model::Hash256::from_bytes([7; 32]),
                signature_hash: kin_model::Hash256::from_bytes([8; 32]),
                behavior_hash: kin_model::Hash256::from_bytes([9; 32]),
                equivalence_hash: kin_model::Hash256::from_bytes([0; 32]),
                stability_score: 1.0,
            },
            file_origin: Some(kin_model::FilePathId::new("selected/compose.yaml")),
            span: None,
            signature: format!("fn {name}()"),
            visibility: kin_model::Visibility::Public,
            role: kin_model::EntityRole::Source,
            doc_summary: None,
            metadata: kin_model::EntityMetadata::default(),
            lineage_parent: None,
            created_in: None,
            superseded_by: None,
        };
        let id = entity.id;
        state
            .graph
            .apply_transaction_delta(&kin_model::TransactionDelta {
                entity_deltas: vec![kin_model::EntityDelta::Added { new: entity }],
                ..kin_model::TransactionDelta::default()
            })
            .unwrap();
        id
    }

    /// The daemon query graph legitimately runs ahead of workspace authority:
    /// enrichment is published into it continuously and reaches authority only
    /// at commit. A switch must plan around that lead rather than refuse it.
    #[cfg(unix)]
    #[tokio::test]
    async fn switch_tolerates_derived_semantics_the_workspace_has_not_published() {
        let (state, _layout, _repository, _main, _feature) =
            universal_branch_test_state("switch-derived-lead");
        install_unpublished_derived_entity(&state, "enriched_ahead_of_authority");

        let switch = kin_cli::commands::branch::BranchRequest::Switch {
            name: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("derived-lead-test"),
        };
        let (status, body) = post_branch_request(Arc::clone(&state), &switch, None).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "unpublished derived enrichment must not wedge a switch: {}",
            String::from_utf8_lossy(&body)
        );
    }

    /// The lead that is tolerated above is strictly additive. A daemon that
    /// dropped semantics authority owns is answering from something other than
    /// graph truth, and must still refuse.
    #[cfg(unix)]
    #[tokio::test]
    async fn switch_refuses_a_daemon_that_lost_authority_owned_semantics() {
        let (state, _layout, _repository, _main, _feature) =
            universal_branch_test_state("switch-lost-authority");
        install_unpublished_derived_entity(&state, "published_then_lost");
        // Commit so the entity is authority-owned rather than merely derived.
        let committed = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "publish the derived entity into authority"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(committed.status(), StatusCode::OK);

        let authority_owned = state
            .graph
            .to_snapshot()
            .entities
            .values()
            .find(|entity| entity.name == "published_then_lost")
            .cloned()
            .expect("the commit publishes the entity into workspace authority");
        state
            .graph
            .apply_transaction_delta(&kin_model::TransactionDelta {
                entity_deltas: vec![kin_model::EntityDelta::Removed {
                    old: authority_owned,
                }],
                ..kin_model::TransactionDelta::default()
            })
            .unwrap();

        let switch = kin_cli::commands::branch::BranchRequest::Switch {
            name: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("lost-authority-test"),
        };
        let (status, body) = post_branch_request(Arc::clone(&state), &switch, None).await;
        assert_eq!(
            status,
            StatusCode::CONFLICT,
            "a daemon missing authority-owned semantics must refuse: {}",
            String::from_utf8_lossy(&body)
        );
        let message = String::from_utf8_lossy(&body);
        assert!(
            message.contains("no longer holds the repository workspace authority"),
            "{message}"
        );
    }

    /// The daemon-side transition is planned before the authority transaction
    /// commits, and the enrichment worker writes into the live graph without
    /// taking the coordination gate or the persistence lock. An enrichment tick
    /// that lands in that window must not leave authority at the new generation
    /// with the daemon cursor still on the old one, which is the same wedge one
    /// step later: finalization therefore plans against the graph it is
    /// installing into rather than against the plan-time snapshot.
    #[cfg(unix)]
    #[tokio::test]
    async fn switch_survives_enrichment_that_lands_after_the_authority_commit() {
        let (state, _layout, _repository, _main, _feature) =
            universal_branch_test_state("switch-enrichment-window");
        let generation_before = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::SeqCst);
        state
            .repository_command_enrich_after_authority_once
            .store(true, std::sync::atomic::Ordering::SeqCst);

        let switch = kin_cli::commands::branch::BranchRequest::Switch {
            name: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("enrichment-window-test"),
        };
        let (status, body) = post_branch_request(Arc::clone(&state), &switch, None).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "enrichment landing after the authority commit must not fail the switch: {}",
            String::from_utf8_lossy(&body)
        );
        assert_eq!(
            state
                .snapshot_generation
                .load(std::sync::atomic::Ordering::SeqCst),
            generation_before + 1,
            "the daemon cursor must follow the authority commit the switch just made"
        );

        // The wedge is the next command, not this one: a daemon cursor left
        // behind authority refuses every freshness-gated command after it.
        let back = kin_cli::commands::branch::BranchRequest::Switch {
            name: kin_model::RefName::branch(b"main").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("enrichment-window-test"),
        };
        let (status, body) = post_branch_request(Arc::clone(&state), &back, None).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "the command after the enrichment window must not be wedged: {}",
            String::from_utf8_lossy(&body)
        );
    }

    /// A seal must leave the daemon and repository authority agreeing, so the
    /// ready commands still work against the workspace it returned.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_stash_leaves_ready_commands_working_on_the_returned_workspace() {
        let (state, _layout, repository, _main, _feature) =
            universal_branch_test_state("stash-then-ready");
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: dirty\n",
        )
        .unwrap();
        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let (status, body) = post_stash_request(Arc::clone(&state), &stash_pop()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));

        let switch = kin_cli::commands::branch::BranchRequest::Switch {
            name: kin_model::RefName::branch(b"feature").unwrap(),
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("stash-then-ready-test"),
        };
        let (status, body) = post_branch_request(Arc::clone(&state), &switch, None).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "a sealed and returned workspace must still switch branches: {}",
            String::from_utf8_lossy(&body)
        );
    }

    /// Restore must refuse a base that moved after the seal instead of
    /// replanning the sealed state onto it.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_stash_refuses_restore_onto_moved_authority() {
        let (state, _layout, repository, _main, _feature) =
            universal_branch_test_state("stash-moved-authority");
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: dirty\n",
        )
        .unwrap();
        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));

        std::fs::write(
            repository.join("selected/Independent.md"),
            b"authority moved after the seal\n",
        )
        .unwrap();
        let committed = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "move authority past the sealed stash"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(committed.status(), StatusCode::OK);

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_pop()).await;
        assert_eq!(status, StatusCode::CONFLICT);
        let message = String::from_utf8_lossy(&body);
        assert!(
            message.contains("does not replan a sealed workspace state onto a base it was never"),
            "{message}"
        );
        assert_eq!(
            stash_entries(Arc::clone(&state)).await.len(),
            1,
            "a refused restore leaves the sealed state exactly where it was"
        );
        assert_eq!(
            std::fs::read(repository.join("selected/compose.yaml")).unwrap(),
            b"services:\n  api:\n    image: main\n",
            "a refused restore projects nothing"
        );
    }

    /// Both directions fail closed: nothing to seal is a refusal, and a
    /// workspace holding its own graph-owned changes is never overwritten.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_stash_refuses_sealing_a_clean_workspace_and_restoring_over_a_dirty_one() {
        let (state, _layout, repository, _main, _feature) =
            universal_branch_test_state("stash-fail-closed");

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::CONFLICT);
        assert!(
            String::from_utf8_lossy(&body).contains("no graph-owned changes to seal"),
            "{}",
            String::from_utf8_lossy(&body)
        );

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_pop()).await;
        assert_eq!(status, StatusCode::CONFLICT);
        assert!(
            String::from_utf8_lossy(&body).contains("no sealed stash to restore"),
            "{}",
            String::from_utf8_lossy(&body)
        );

        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: first\n",
        )
        .unwrap();
        let (status, body) = post_stash_request(Arc::clone(&state), &stash_push()).await;
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));

        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"services:\n  api:\n    image: second\n",
        )
        .unwrap();

        let (status, body) = post_stash_request(Arc::clone(&state), &stash_pop()).await;
        assert_eq!(status, StatusCode::CONFLICT);
        assert!(
            String::from_utf8_lossy(&body).contains("holds graph-owned changes of its own"),
            "{}",
            String::from_utf8_lossy(&body)
        );
        assert_eq!(
            stash_entries(Arc::clone(&state)).await.len(),
            1,
            "the refused restore left the sealed state intact"
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn command_checkout_projection_only_repairs_universal_bytes_and_replays_after_restart() {
        use std::os::unix::fs::{symlink, PermissionsExt as _};

        let (state, layout, repository, _main, _feature) =
            universal_branch_test_state("checkout-projection-only");
        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let roots_before = authority.manager.read_authority().roots().clone();
        drop(authority);
        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"dirty compose bytes\n",
        )
        .unwrap();
        std::fs::write(repository.join("selected/data.bin"), b"dirty binary").unwrap();
        let mut permissions = std::fs::metadata(repository.join("selected/run-tool"))
            .unwrap()
            .permissions();
        permissions.set_mode(0o644);
        std::fs::set_permissions(repository.join("selected/run-tool"), permissions).unwrap();
        std::fs::remove_file(repository.join("selected/current-compose")).unwrap();
        symlink("data.bin", repository.join("selected/current-compose")).unwrap();
        std::fs::write(repository.join("outside.txt"), b"outside dirty preserved\n").unwrap();
        let request = kin_cli::commands::checkout::CheckoutRequest {
            path: Some("selected".to_string()),
            path_hex: None,
            change_id: None,
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("checkout-projection-only-test"),
        };
        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/checkout")
                    .header("content-type", "application/json")
                    .body(Body::from(serde_json::to_vec(&request).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let response: kin_cli::commands::checkout::CheckoutResponse =
            serde_json::from_slice(&body).unwrap();
        assert!(response.report.unwrap().projection_only);
        assert_eq!(
            std::fs::read(repository.join("selected/compose.yaml")).unwrap(),
            b"services:\n  api:\n    image: main\n"
        );
        assert_eq!(
            std::fs::read(repository.join("selected/data.bin")).unwrap(),
            [0_u8, 0xff, 0x10, 0x00]
        );
        assert_ne!(
            std::fs::metadata(repository.join("selected/run-tool"))
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
        assert_eq!(
            std::fs::read_link(repository.join("selected/current-compose")).unwrap(),
            FsPath::new("compose.yaml")
        );
        assert_eq!(
            std::fs::read(repository.join("outside.txt")).unwrap(),
            b"outside dirty preserved\n"
        );
        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        assert_eq!(authority.manager.read_authority().roots(), &roots_before);
        drop(authority);

        std::fs::write(
            repository.join("selected/compose.yaml"),
            b"post-completion edit\n",
        )
        .unwrap();
        drop(state);
        let reopened = Arc::new(DaemonState::open(layout.clone()).unwrap());
        let replay = router(Arc::clone(&reopened))
            .oneshot(
                Request::post("/commands/checkout")
                    .header("content-type", "application/json")
                    .body(Body::from(serde_json::to_vec(&request).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = replay.status();
        let body = axum::body::to_bytes(replay.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let replay: kin_cli::commands::checkout::CheckoutResponse =
            serde_json::from_slice(&body).unwrap();
        let report = replay.report.unwrap();
        assert!(report.projection_only);
        assert!(report.idempotent);
        assert!(!replay.mutated);
        assert_eq!(
            std::fs::read(repository.join("selected/compose.yaml")).unwrap(),
            b"post-completion edit\n"
        );
        let authority = ActiveApiRepositoryAuthority::open(&reopened).unwrap();
        assert_eq!(authority.manager.read_authority().roots(), &roots_before);
    }

    #[cfg(unix)]
    fn copy_directory_tree(source: &FsPath, target: &FsPath) {
        std::fs::create_dir(target).unwrap();
        for entry in std::fs::read_dir(source).unwrap() {
            let entry = entry.unwrap();
            let source_path = entry.path();
            let target_path = target.join(entry.file_name());
            if entry.file_type().unwrap().is_dir() {
                copy_directory_tree(&source_path, &target_path);
            } else {
                std::fs::copy(source_path, target_path).unwrap();
            }
        }
    }

    #[cfg(unix)]
    fn pinned_repository_namespace(state: &DaemonState) -> PathBuf {
        let manifest =
            kin_core::manifest::KinManifest::load(&state.layout.manifest_path()).unwrap();
        state.layout.kindb_dir().join(manifest.repo_id)
    }

    /// Prove the retained per-repository capability, not only the storage root,
    /// is what checkout answers from: a byte-identical repository namespace
    /// copied over the same ambient path mid-daemon-lifetime is refused.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_checkout_refuses_replaced_repository_namespace_without_mutation() {
        let state = committed_test_state();
        let checkout = |operation_id| kin_cli::commands::checkout::CheckoutRequest {
            path: Some("README.md".to_string()),
            path_hex: None,
            change_id: None,
            operation_id,
            actor: AuthorId::new("checkout-namespace-replacement-test"),
        };

        // Establish the baseline: the same request succeeds while the pinned
        // namespace is intact, so the later refusal cannot be blamed on an
        // unrelated defect in the request itself.
        let accepted = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/checkout")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&checkout(kin_model::OperationId::new())).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(accepted.status(), StatusCode::OK);
        let generation_before = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::SeqCst);
        let roots_before = state.graph.compute_root_hash();

        // Stage both halves of the swap outside the storage root: a spare
        // namespace directory inside it would be listed as a second repository
        // resolving onto the retained identity, which is a different refusal.
        let namespace = pinned_repository_namespace(&state);
        let replacement = state.layout.root().join("namespace-replacement");
        let displaced = state.layout.root().join("namespace-displaced");
        copy_directory_tree(&namespace, &replacement);
        std::fs::rename(&namespace, &displaced).unwrap();
        std::fs::rename(&replacement, &namespace).unwrap();

        let refused = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/checkout")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&checkout(kin_model::OperationId::new())).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = refused.status();
        let body = axum::body::to_bytes(refused.into_body(), 64 * 1024)
            .await
            .unwrap();
        let body = String::from_utf8_lossy(&body);
        assert_eq!(status, StatusCode::CONFLICT, "{body}");
        assert!(
            body.contains("pinned at startup is no longer the one at that path"),
            "refusal must name the pinned-namespace mismatch: {body}"
        );
        assert_eq!(
            state
                .snapshot_generation
                .load(std::sync::atomic::Ordering::SeqCst),
            generation_before,
            "a refused checkout must not advance repository authority"
        );
        assert_eq!(state.graph.compute_root_hash(), roots_before);
    }

    /// A repository namespace detached from under a live daemon must fail
    /// closed rather than fall back to the storage root or a fresh namespace.
    #[cfg(unix)]
    #[tokio::test]
    async fn command_checkout_refuses_detached_repository_namespace_without_mutation() {
        let state = committed_test_state();
        let generation_before = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::SeqCst);

        let namespace = pinned_repository_namespace(&state);
        std::fs::rename(&namespace, state.layout.root().join("namespace-detached")).unwrap();

        let request = kin_cli::commands::checkout::CheckoutRequest {
            path: Some("README.md".to_string()),
            path_hex: None,
            change_id: None,
            operation_id: kin_model::OperationId::new(),
            actor: AuthorId::new("checkout-namespace-detach-test"),
        };
        let refused = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/checkout")
                    .header("content-type", "application/json")
                    .body(Body::from(serde_json::to_vec(&request).unwrap()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = refused.status();
        let body = axum::body::to_bytes(refused.into_body(), 64 * 1024)
            .await
            .unwrap();
        let body = String::from_utf8_lossy(&body);
        assert_eq!(status, StatusCode::CONFLICT, "{body}");
        assert!(
            body.contains("pinned at startup is no longer the one at that path"),
            "refusal must name the pinned-namespace mismatch: {body}"
        );
        assert!(
            body.contains("detached after this backend"),
            "refusal must name the detachment rather than a generic miss: {body}"
        );
        assert_eq!(
            state
                .snapshot_generation
                .load(std::sync::atomic::Ordering::SeqCst),
            generation_before
        );
    }

    #[tokio::test]
    async fn exact_source_route_reads_repository_cas_and_ignores_checkout_bytes() {
        let state = test_state();
        let repo_id = state.cached_repo_id.clone();
        let change_id = install_repository_file(&state, "README.md", b"graph-owned source\n");
        let app = router_with_auth(Arc::clone(&state), Some("exact-source-token".to_string()));
        let path = format!("/repos/{repo_id}/archive/tar/{change_id}");

        let unauthenticated = app
            .clone()
            .oneshot(Request::get(&path).body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(unauthenticated.status(), StatusCode::UNAUTHORIZED);

        let request = || {
            Request::get(&path)
                .header(header::AUTHORIZATION, "Bearer exact-source-token")
                .body(Body::empty())
                .unwrap()
        };
        let first = app.clone().oneshot(request()).await.unwrap();
        assert_eq!(first.status(), StatusCode::OK);
        assert_eq!(
            first.headers()["x-kin-source-change-id"],
            change_id.to_string()
        );
        let manifest = first.headers()["x-kin-source-manifest-sha256"].clone();
        let first = axum::body::to_bytes(first.into_body(), 1024 * 1024)
            .await
            .unwrap();
        assert!(!first.is_empty());
        let first_digest: [u8; 32] = Sha256::digest(&first).into();
        // The archive body deliberately retains the process-wide memory
        // admission permit for as long as its bytes are alive. Release that
        // first allocation before asking the single-flight endpoint to
        // reproduce it, then compare the exact content identity.
        drop(first);

        std::fs::write(
            state.layout.working_dir().join("README.md"),
            b"unadmitted checkout decoy\n",
        )
        .unwrap();
        let repeated = app.oneshot(request()).await.unwrap();
        assert_eq!(repeated.status(), StatusCode::OK);
        assert_eq!(repeated.headers()["x-kin-source-manifest-sha256"], manifest);
        let repeated = axum::body::to_bytes(repeated.into_body(), 1024 * 1024)
            .await
            .unwrap();
        let repeated_digest: [u8; 32] = Sha256::digest(&repeated).into();
        assert_eq!(repeated_digest, first_digest);
    }

    #[tokio::test]
    async fn health_returns_ok_with_extended_fields() {
        let state = test_state();
        let expected_generation = DaemonState::read_generation_marker(&state.layout);
        let app = router(state);
        let response = app
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let json: HealthResponse = serde_json::from_slice(&body).unwrap();
        assert_eq!(json.status, "ok");
        assert!(json.uptime_seconds < 5);
        assert!(json.graph_entity_count.is_some());
        assert_eq!(json.build.sha, kin_buildinfo::get().sha);
        assert_eq!(json.build.dirty, kin_buildinfo::get().dirty);
        assert!(!json.build.built_at.is_empty());
        assert!(
            !json.embed_persistence_unavailable,
            "local repository authority must allow derived vector persistence"
        );
        assert!(
            json.vector_index_discarded.is_none(),
            "a repository with no index to discard must not report one: {:?}",
            json.vector_index_discarded
        );
        assert!(
            !json.filesystem_reconcile_disabled,
            "local authority remains file-compatible unless explicitly disabled"
        );
        assert_eq!(json.graph_generation, expected_generation);
        let coordination = json
            .coordination
            .expect("new daemon must attest coordination");
        assert_eq!(coordination.schema, "kin.coordination-enforcement.v1");
        assert!(coordination.surfaces.mcp_transaction_entity);
        assert!(!coordination.surfaces.contract);
        assert!(!coordination.contract_scope_claim_eligible);
        assert_eq!(json.coordination_event_persist_failures, Some(0));

        let mut legacy: serde_json::Value = serde_json::from_slice(&body).unwrap();
        legacy.as_object_mut().unwrap().remove("coordination");
        legacy
            .as_object_mut()
            .unwrap()
            .remove("coordination_event_persist_failures");
        let legacy: HealthResponse = serde_json::from_value(legacy).unwrap();
        assert!(legacy.coordination.is_none());
        assert!(legacy.coordination_event_persist_failures.is_none());
    }

    async fn health_json(state: Arc<DaemonState>) -> HealthResponse {
        let response = router(state)
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        serde_json::from_slice(&body).unwrap()
    }

    /// The whole point of the supervisor, end to end on the surface a user or
    /// agent actually reads.
    ///
    /// A pass that declares itself working and never records anything is exactly
    /// the shape of a daemon spending a machine with no signal, and the daemon
    /// must stop it and say so. Time is supplied rather than slept: the sweep
    /// takes the instant it judges against, so the real production threshold is
    /// exercised without the test waiting ten minutes for it.
    #[tokio::test]
    async fn a_wedged_background_pass_is_stopped_and_its_reason_reaches_health() {
        let state = test_state();
        let pass = state
            .background_work
            .pass(crate::background_work::PASS_EMBED);
        let base = std::time::Instant::now();
        pass.working(base);

        assert!(
            health_json(Arc::clone(&state)).await.status == "ok",
            "a pass that has only just started working is not yet a fault"
        );

        let past_threshold =
            base + crate::background_work::DEFAULT_STALL_THRESHOLD + Duration::from_secs(1);
        assert_eq!(state.background_work.sweep(past_threshold).len(), 1);

        let json = health_json(state).await;
        assert_eq!(
            json.status, "attention",
            "a stopped background pass must not leave health reporting ok"
        );
        let report = json
            .background_passes
            .iter()
            .find(|report| report.name == crate::background_work::PASS_EMBED)
            .expect("the stopped pass must appear in health");
        assert_eq!(report.state, "stopped");
        let reason = report
            .stopped_reason
            .as_deref()
            .expect("a stopped pass must carry a reason");
        assert!(
            reason.contains("without recording any progress"),
            "the reason must say why the pass was stopped: {reason}"
        );
        assert!(
            reason.contains("the daemon keeps serving"),
            "the reason must say what still works: {reason}"
        );
    }

    /// The falsification for the test above, and the property that makes the
    /// mechanism safe to ship.
    ///
    /// Same pass, same working stretch, same sweep instant — the ONLY difference
    /// is that this one reports progress. A supervisor that stopped long-running
    /// work rather than stalled work would pass the test above and fail here.
    #[tokio::test]
    async fn a_long_pass_that_reports_progress_is_never_stopped() {
        let state = test_state();
        let pass = state
            .background_work
            .pass(crate::background_work::PASS_EMBED);
        let base = std::time::Instant::now();
        pass.working(base);

        let threshold = crate::background_work::DEFAULT_STALL_THRESHOLD;
        // Work for ten times the threshold, recording progress throughout.
        for step in 1..=20u32 {
            let now = base + threshold.mul_f64(f64::from(step) / 2.0);
            pass.advanced(32, now);
            assert!(
                state.background_work.sweep(now).is_empty(),
                "a pass recording progress must never be stopped"
            );
        }

        let json = health_json(state).await;
        assert_eq!(json.status, "ok");
        let report = json
            .background_passes
            .iter()
            .find(|report| report.name == crate::background_work::PASS_EMBED)
            .expect("a healthy pass is still disclosed");
        assert_eq!(report.state, "working");
        assert_eq!(report.progress, 32 * 20);
        assert!(report.stopped_reason.is_none());
    }

    /// Exhausting a retry ladder's cumulative budget parks the work with a
    /// reason on the same surface, rather than retrying at the backoff ceiling
    /// for as long as the process lives.
    #[tokio::test]
    async fn retry_budget_exhaustion_parks_the_pass_with_a_reason_in_health() {
        let state = test_state();
        let pass = state
            .background_work
            .pass(crate::background_work::PASS_EMBED);
        let budget = Duration::from_secs(120);

        assert!(pass.charge_retry(Duration::from_secs(60), budget, "the embedding worker"));
        assert_eq!(health_json(Arc::clone(&state)).await.status, "ok");

        assert!(!pass.charge_retry(Duration::from_secs(60), budget, "the embedding worker"));

        let json = health_json(state).await;
        assert_eq!(json.status, "attention");
        let reason = json
            .background_passes
            .iter()
            .find(|report| report.name == crate::background_work::PASS_EMBED)
            .and_then(|report| report.stopped_reason.clone())
            .expect("a parked pass must carry a reason");
        assert!(
            reason.contains("cumulative retry backoff"),
            "the reason must name the budget that was spent: {reason}"
        );
    }

    /// The counter reaches the surface a reader actually queries.
    ///
    /// Everything either side of this is covered elsewhere — the cache counts in
    /// its own tests, the renderer is covered in kin-cli — so without this the
    /// one line joining them would be compile-checked and nothing more, and
    /// deleting it would leave every test green while the number vanished from
    /// the product.
    #[tokio::test]
    async fn resources_report_the_authority_loads_this_daemon_has_paid_for() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let response = router(state)
            .oneshot(
                Request::post("/commands/resources")
                    .header("content-type", "application/json")
                    .body(Body::from(json!({ "json": false }).to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 512 * 1024)
            .await
            .unwrap();
        let resources: kin_cli::commands::resources::CommandResourcesResponse =
            serde_json::from_slice(&body).unwrap();

        // Zero, not absent: this daemon has opened no durable authority yet, and
        // that is an answer. Absent would mean the daemon never reported one.
        assert_eq!(
            resources.daemon_work.authority_loads,
            Some(0),
            "a daemon that has loaded nothing must say zero, not say nothing"
        );
        assert!(
            resources.text.contains("Authority loads: 0"),
            "the count must reach the text surface, not only the JSON: {}",
            resources.text
        );
    }

    /// A daemon that has started no background pass discloses that honestly,
    /// and does not invent a cumulative CPU figure it has not measured.
    #[tokio::test]
    async fn health_discloses_no_passes_and_no_cpu_before_anything_runs() {
        let json = health_json(test_state()).await;
        assert_eq!(json.status, "ok");
        assert!(json.background_passes.is_empty());
        assert!(
            json.daemon_cpu_seconds.is_none(),
            "an unsampled CPU total must be absent rather than reported as zero"
        );
    }

    async fn advertised_repo_id(state: Arc<DaemonState>) -> String {
        let response = router(state)
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        serde_json::from_slice::<HealthResponse>(&body)
            .unwrap()
            .repo_id
    }

    async fn repo_route(state: Arc<DaemonState>, path: &str) -> (StatusCode, Vec<u8>) {
        let response = router(state)
            .oneshot(Request::get(path).body(Body::empty()).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 1024 * 1024)
            .await
            .unwrap();
        (status, body.to_vec())
    }

    /// Drive the real spine ingest route, body and all, exactly as the hosted
    /// import orchestrator does. Going through `router` rather than calling the
    /// state method keeps the status code under test the one a client actually
    /// receives.
    async fn spine_ingest(state: Arc<DaemonState>, repo_id: &str) -> (StatusCode, Vec<u8>) {
        let response = router(state)
            .oneshot(
                Request::post(format!("/spine/repos/{repo_id}/ingest"))
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&serde_json::json!({ "repo": repo_id })).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 1024 * 1024)
            .await
            .unwrap();
        (status, body.to_vec())
    }

    /// The identity contract a client depends on: read `repo_id` off `/health`
    /// and every `/repos/{repo_id}/…` route resolves it. Two key spaces here
    /// meant a caller that trusted the advertised id got a storage-mode 500 on
    /// every repo-scoped call against a perfectly healthy daemon.
    #[tokio::test]
    async fn health_repo_id_addresses_every_repo_scoped_route() {
        let state = test_state();
        let repo_id = advertised_repo_id(Arc::clone(&state)).await;
        assert!(!repo_id.trim().is_empty(), "/health must advertise an id");

        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{repo_id}/health")).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "advertised repo id must route: {}",
            String::from_utf8_lossy(&body)
        );
        let health: RepoHealthResponse = serde_json::from_slice(&body).unwrap();
        assert_eq!(
            health.repo_id, repo_id,
            "the repo route must echo the advertised identity back"
        );

        for path in [
            format!("/repos/{repo_id}/entities"),
            format!("/repos/{repo_id}/refs"),
            format!("/repos/{repo_id}/files"),
            format!("/repos/{repo_id}/history"),
            format!("/repos/{repo_id}/provenance/verify"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            assert_eq!(
                status,
                StatusCode::OK,
                "{path} must accept the advertised repo id: {}",
                String::from_utf8_lossy(&body)
            );
        }

        // /repos lists the same key space the advertised id belongs to.
        let (status, body) = repo_route(Arc::clone(&state), "/repos").await;
        assert_eq!(status, StatusCode::OK);
        let listed: ReposResponse = serde_json::from_slice(&body).unwrap();
        assert!(
            listed.repos.contains(&repo_id),
            "the advertised id must appear in the repo listing: {:?}",
            listed.repos
        );
    }

    /// An id this daemon does not serve is an identity mismatch, not a broken
    /// daemon: 404 naming the id that is served, rather than the lazy
    /// multi-repo loader's "no storage backend configured" 500.
    ///
    /// The route list covers every surface the identity resolution reaches,
    /// including the four that resolve through `repository_authority_snapshot`.
    /// Those short-circuit on the advertised id, so driving them with an id the
    /// daemon serves exercises none of this: only an unserved id reaches
    /// `repo_scoped_graph` through them.
    #[tokio::test]
    async fn an_unserved_repo_id_is_an_identity_mismatch_rather_than_a_storage_failure() {
        let state = test_state();
        let served = advertised_repo_id(Arc::clone(&state)).await;
        let unserved = format!("not-{served}");
        // Parses as a canonical semantic change id, so the archive route
        // reaches identity resolution instead of refusing on the id shape.
        let well_formed_change = "a".repeat(64);

        for path in [
            format!("/repos/{unserved}/health"),
            format!("/repos/{unserved}/entities"),
            format!("/repos/{unserved}/provenance/verify"),
            format!("/repos/{unserved}/files"),
            format!("/repos/{unserved}/refs"),
            format!("/repos/{unserved}/history"),
            format!("/repos/{unserved}/archive/tar/{well_formed_change}"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            assert_eq!(status, StatusCode::NOT_FOUND, "{path}");
            let message = String::from_utf8_lossy(&body);
            assert!(
                message.contains(&served) && message.contains(&unserved),
                "the refusal must name both the served and requested ids: {message}"
            );
            assert!(
                !message.contains("no storage backend configured"),
                "an identity mismatch must not read as a storage-mode failure: {message}"
            );
        }
    }

    /// A `StorageBackend` that faults on demand for named repositories,
    /// delegating everything else to a real local backend.
    ///
    /// The faults it raises are the ones a hosted backend actually raises for a
    /// repository it is configured to serve: an unreachable object store,
    /// expired credentials, a snapshot authority that disagrees with the
    /// acknowledged head, or a corrupt delta chain. All of them arrive as an
    /// `Err` out of the recovery read, which is the single path
    /// `load_recovered_snapshot` takes, so fault injection is scoped to exactly
    /// the three reads that path makes.
    ///
    /// Every other trait method forwards to the inner backend, including the
    /// ones whose trait defaults would answer instead of delegating. That is
    /// not tidiness: `supports_incremental_deltas` defaults to `false` and the
    /// whole source-blob family defaults to "not supported by this backend",
    /// so a partially-forwarding fixture silently downgrades the very
    /// capabilities a hosted backend has. A test reusing it would then be
    /// measuring the fixture's degraded shape and reporting it as hosted
    /// behavior.
    ///
    /// The single method deliberately left on its trait default is
    /// `compact_deltas`, which `LocalFileBackend` also leaves defaulted. That
    /// default composes through this type's own reads, so compaction stays
    /// fault-aware instead of routing around the switch.
    struct RepoFaultBackend {
        inner: kin_db::LocalFileBackend,
        faulting: FaultSwitch,
    }

    /// Handle the test keeps after the backend is moved into the daemon, so a
    /// fault can be armed once the daemon has already opened healthy.
    #[derive(Clone)]
    struct FaultSwitch(Arc<std::sync::Mutex<std::collections::HashSet<String>>>);

    impl FaultSwitch {
        fn start_faulting(&self, repo_id: &str) {
            self.0.lock().unwrap().insert(repo_id.to_string());
        }

        fn fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.0.lock().unwrap().contains(repo_id).then(|| {
                kin_db::KinDbError::StorageError(format!(
                    "{BACKEND_FAULT_TEXT} while reading {repo_id}"
                ))
            })
        }
    }

    impl RepoFaultBackend {
        fn new(path: &std::path::Path) -> (Self, FaultSwitch) {
            let faulting = FaultSwitch(Arc::new(std::sync::Mutex::new(
                std::collections::HashSet::new(),
            )));
            (
                Self {
                    inner: kin_db::LocalFileBackend::new(path),
                    faulting: faulting.clone(),
                },
                faulting,
            )
        }

        fn fault_for(&self, repo_id: &str) -> Option<kin_db::KinDbError> {
            self.faulting.fault_for(repo_id)
        }
    }

    const BACKEND_FAULT_TEXT: &str = "object store unreachable";

    impl kin_db::StorageBackend for RepoFaultBackend {
        fn supports_incremental_deltas(&self) -> bool {
            self.inner.supports_incremental_deltas()
        }

        fn load_recovery_state(
            &self,
            repo_id: &str,
        ) -> std::result::Result<kin_db::SnapshotRecoveryState, kin_db::KinDbError> {
            match self.fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_recovery_state(repo_id),
            }
        }

        fn load_snapshot_authority(
            &self,
            repo_id: &str,
        ) -> std::result::Result<Option<kin_db::SnapshotAuthority>, kin_db::KinDbError> {
            match self.fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_snapshot_authority(repo_id),
            }
        }

        fn load_snapshot(
            &self,
            repo_id: &str,
        ) -> std::result::Result<Option<(Vec<u8>, kin_db::Generation)>, kin_db::KinDbError>
        {
            match self.fault_for(repo_id) {
                Some(error) => Err(error),
                None => self.inner.load_snapshot(repo_id),
            }
        }

        fn save_source_blob(
            &self,
            repo_id: &str,
            digest: [u8; 32],
            data: &[u8],
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.save_source_blob(repo_id, digest, data)
        }

        fn load_source_blob(
            &self,
            repo_id: &str,
            digest: [u8; 32],
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            self.inner.load_source_blob(repo_id, digest)
        }

        fn load_source_blob_bounded(
            &self,
            repo_id: &str,
            digest: [u8; 32],
            max_bytes: u64,
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            self.inner
                .load_source_blob_bounded(repo_id, digest, max_bytes)
        }

        fn with_verified_source_blob_batch(
            &self,
            repo_id: &str,
            operation: &mut dyn FnMut(
                &dyn kin_db::VerifiedSourceBlobBatch,
            ) -> std::result::Result<(), kin_db::KinDbError>,
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner
                .with_verified_source_blob_batch(repo_id, operation)
        }

        fn source_blob_len(
            &self,
            repo_id: &str,
            digest: [u8; 32],
        ) -> std::result::Result<Option<u64>, kin_db::KinDbError> {
            self.inner.source_blob_len(repo_id, digest)
        }

        fn save_snapshot(
            &self,
            repo_id: &str,
            data: &[u8],
            expected_gen: kin_db::Generation,
        ) -> std::result::Result<kin_db::Generation, kin_db::KinDbError> {
            self.inner.save_snapshot(repo_id, data, expected_gen)
        }

        fn save_snapshot_classified(
            &self,
            repo_id: &str,
            data: &[u8],
            expected_cursor: kin_db::SnapshotCursor,
        ) -> kin_db::SnapshotSaveOutcome {
            self.inner
                .save_snapshot_classified(repo_id, data, expected_cursor)
        }

        fn save_snapshot_validated(
            &self,
            repo_id: &str,
            data: &[u8],
            expected: kin_db::SnapshotCursor,
            history_validator_version: Option<u32>,
        ) -> kin_db::SnapshotSaveOutcome {
            self.inner
                .save_snapshot_validated(repo_id, data, expected, history_validator_version)
        }

        fn record_history_validation(
            &self,
            repo_id: &str,
            generation: kin_db::Generation,
            snapshot_sha256: &str,
            validator_version: u32,
        ) -> std::result::Result<bool, kin_db::KinDbError> {
            self.inner.record_history_validation(
                repo_id,
                generation,
                snapshot_sha256,
                validator_version,
            )
        }

        fn save_delta(
            &self,
            repo_id: &str,
            delta_data: &[u8],
            base_gen: kin_db::Generation,
        ) -> std::result::Result<kin_db::Generation, kin_db::KinDbError> {
            self.inner.save_delta(repo_id, delta_data, base_gen)
        }

        fn load_deltas_since(
            &self,
            repo_id: &str,
            since_gen: kin_db::Generation,
        ) -> std::result::Result<Vec<(Vec<u8>, kin_db::Generation)>, kin_db::KinDbError> {
            self.inner.load_deltas_since(repo_id, since_gen)
        }

        fn clear_deltas(&self, repo_id: &str) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.clear_deltas(repo_id)
        }

        fn save_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
            data: &[u8],
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.save_overlay(repo_id, session_id, data)
        }

        fn load_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
        ) -> std::result::Result<Option<Vec<u8>>, kin_db::KinDbError> {
            self.inner.load_overlay(repo_id, session_id)
        }

        fn delete_overlay(
            &self,
            repo_id: &str,
            session_id: &str,
        ) -> std::result::Result<(), kin_db::KinDbError> {
            self.inner.delete_overlay(repo_id, session_id)
        }

        fn list_repos(&self) -> std::result::Result<Vec<String>, kin_db::KinDbError> {
            self.inner.list_repos()
        }
    }

    /// The shipped hosted shape: one advertised repo, several allowlisted
    /// siblings, none of them pre-warmed into the repo graph map, over a
    /// backend that can be made to fault per repository.
    fn hosted_state_with_allowlist(
        label: &str,
        advertised: &str,
        siblings: &[&str],
    ) -> (Arc<DaemonState>, FaultSwitch) {
        let dir = std::env::temp_dir().join(format!("kin-daemon-{label}-{}", Uuid::new_v4()));
        let kin_dir = dir.join(".kin");
        std::fs::create_dir_all(kin_dir.join("objects")).unwrap();
        std::fs::create_dir_all(kin_dir.join("working")).unwrap();
        let layout = kin_core::KinLayout::new(kin_dir);
        kin_core::manifest::KinManifest::new()
            .save(&layout.manifest_path())
            .unwrap();
        let backend_dir = dir.join("backend");
        std::fs::create_dir_all(&backend_dir).unwrap();

        let (backend, faults) = RepoFaultBackend::new(&backend_dir);
        let allowed: std::collections::HashSet<String> = std::iter::once(advertised)
            .chain(siblings.iter().copied())
            .map(ToOwned::to_owned)
            .collect();
        let state = Arc::new(
            DaemonState::open_with_backend(layout, Box::new(backend), advertised, Some(allowed))
                .unwrap(),
        );
        (state, faults)
    }

    /// The fault fixture must be indistinguishable from the backend it wraps
    /// except when a fault is armed. A trait default answering in place of a
    /// forward is not a smaller lie than a wrong value: it reports "this
    /// backend cannot do that" about a backend that can, so a test reusing the
    /// fixture measures a degraded shape and reports it as hosted behavior.
    #[test]
    fn the_fault_fixture_forwards_the_capabilities_of_the_backend_it_wraps() {
        use kin_db::StorageBackend;

        let dir =
            std::env::temp_dir().join(format!("kin-daemon-fault-fidelity-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let real = kin_db::LocalFileBackend::new(&dir);
        let (fixture, _faults) = RepoFaultBackend::new(&dir);

        assert!(
            real.supports_incremental_deltas(),
            "the wrapped backend is expected to have a delta write path"
        );
        assert_eq!(
            fixture.supports_incremental_deltas(),
            real.supports_incremental_deltas(),
            "a fixture that under-reports delta support sends writes down the wrong path"
        );

        let repo_id = "fidelity-repo";
        let body: &[u8] = b"fn main() {}";
        let digest: [u8; 32] = Sha256::digest(body).into();
        fixture
            .save_source_blob(repo_id, digest, body)
            .expect("the fixture must forward immutable source-blob writes");
        assert_eq!(
            real.load_source_blob(repo_id, digest).unwrap().as_deref(),
            Some(body),
            "the forwarded write must land in the wrapped backend"
        );
        assert_eq!(
            fixture
                .load_source_blob(repo_id, digest)
                .unwrap()
                .as_deref(),
            Some(body)
        );
        assert_eq!(
            fixture
                .load_source_blob_bounded(repo_id, digest, kin_db::MAX_SOURCE_BLOB_BYTES)
                .unwrap()
                .as_deref(),
            Some(body)
        );
        assert_eq!(
            fixture.source_blob_len(repo_id, digest).unwrap(),
            Some(body.len() as u64)
        );

        let mut batched: Option<Vec<u8>> = None;
        fixture
            .with_verified_source_blob_batch(repo_id, &mut |batch| {
                batched = batch
                    .load_verified(kin_db::SourceBlobValidationRequest {
                        digest,
                        max_bytes: kin_db::MAX_SOURCE_BLOB_BYTES,
                    })?
                    .map(|verified| verified.into_bytes());
                Ok(())
            })
            .expect("the fixture must forward verified batch reads");
        assert_eq!(batched.as_deref(), Some(body));
    }

    /// A hosted daemon serves every allowlisted repository, not only the one it
    /// advertises. So a backend fault on an allowlisted sibling is a fault, and
    /// answering 404 there would report a GCS outage or a corrupt delta chain as
    /// a repository this daemon does not have: false on its face, contradicted
    /// by `GET /repos` on the same daemon, and invisible to every retry loop and
    /// 5xx alert that exists to catch exactly that.
    ///
    /// This is the case an identity compare cannot decide, and the reason
    /// addressing is resolved from the served key space before the load rather
    /// than inferred from the failure afterwards.
    #[tokio::test]
    async fn a_backend_fault_on_a_served_sibling_stays_a_fault_rather_than_a_404() {
        let advertised = "primary-repo";
        let sibling = "sibling-repo";
        let (state, faults) = hosted_state_with_allowlist("repo-fault", advertised, &[sibling]);
        assert_eq!(
            advertised_repo_id(Arc::clone(&state)).await,
            advertised,
            "the fixture must advertise the primary id"
        );
        assert!(
            state.serves_repo_id(sibling),
            "the allowlist is the served key space, so the sibling is served"
        );

        faults.start_faulting(sibling);

        for path in [
            format!("/repos/{sibling}/health"),
            format!("/repos/{sibling}/entities"),
            format!("/repos/{sibling}/provenance/verify"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            let message = String::from_utf8_lossy(&body);
            assert_eq!(
                status,
                StatusCode::INTERNAL_SERVER_ERROR,
                "a backend fault on a served repository must stay a fault at {path}: {message}"
            );
            assert!(
                message.contains(BACKEND_FAULT_TEXT),
                "the fault must carry the backend error rather than discard it: {message}"
            );
            assert!(
                !message.contains("does not serve"),
                "a served repository must never be reported as unserved: {message}"
            );
        }

        // The same daemon still refuses an id outside the served key space, and
        // still refuses it as an identity mismatch.
        let unserved = "absent-repo";
        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{unserved}/entities")).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::NOT_FOUND,
            "an id outside the allowlist is an identity mismatch: {message}"
        );
        assert!(
            message.contains(advertised) && message.contains(unserved),
            "the refusal must name both the served and requested ids: {message}"
        );
    }

    /// An allowlisted repository with nothing stored under it is a repository
    /// that is not there, not a daemon that is broken. The backend read
    /// succeeded and reported neither snapshot authority nor deltas, which is a
    /// complete answer. Reporting it as a fault told every client, retry loop,
    /// and 5xx alert that this daemon had failed, when no amount of retrying
    /// makes an absent repository appear.
    ///
    /// It is equally not an identity mismatch: the id IS in this daemon's
    /// served key space, so the refusal must not claim otherwise.
    #[tokio::test]
    async fn an_allowlisted_repo_absent_from_storage_is_missing_rather_than_a_fault() {
        let advertised = "primary-repo";
        let absent = "never-stored-repo";
        let (state, faults) = hosted_state_with_allowlist("repo-absent", advertised, &[absent]);
        assert_eq!(
            advertised_repo_id(Arc::clone(&state)).await,
            advertised,
            "the fixture must advertise the primary id"
        );
        assert!(
            state.serves_repo_id(absent),
            "the allowlist is the served key space, so the absent id is served"
        );

        for path in [
            format!("/repos/{absent}/health"),
            format!("/repos/{absent}/entities"),
            format!("/repos/{absent}/provenance/verify"),
        ] {
            let (status, body) = repo_route(Arc::clone(&state), &path).await;
            let message = String::from_utf8_lossy(&body);
            assert_eq!(
                status,
                StatusCode::NOT_FOUND,
                "a served repository absent from storage must be missing at {path}: {message}"
            );
            assert!(
                message.contains(advertised) && message.contains(absent),
                "the refusal must name both the served and requested ids: {message}"
            );
            assert!(
                !message.contains("does not serve"),
                "an allowlisted repository must not be reported as unserved: {message}"
            );
        }

        // The advertised repository still answers on the same daemon, so the
        // 404s above are about that repository rather than a daemon-wide state.
        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{advertised}/entities")).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "the advertised repo must stay routable: {}",
            String::from_utf8_lossy(&body)
        );

        // Absence is decided by what the load reported, not by the id: the very
        // same id over a backend that cannot answer is still a fault.
        faults.start_faulting(absent);
        let (status, body) =
            repo_route(Arc::clone(&state), &format!("/repos/{absent}/entities")).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::INTERNAL_SERVER_ERROR,
            "a backend that cannot answer is still a fault: {message}"
        );
        assert!(
            message.contains(BACKEND_FAULT_TEXT),
            "the fault must carry the backend error rather than discard it: {message}"
        );
    }

    /// The spine ingest route resolves a repository by id just as the
    /// `/repos/{repo_id}` routes do, so it owes a caller the same three
    /// answers. It gave one: every outcome, a mis-addressed request included,
    /// arrived as a 500.
    ///
    /// This is the shape the control plane actually meets. The import
    /// orchestrator POSTs one ingest per cataloged repo, so a pod whose
    /// `KIN_REPO_IDS` omits one of them answered "this daemon failed" to a
    /// question about which pod owns that repository. The orchestrator then
    /// retried, and no number of retries moves a repository into a key space
    /// that excludes it, while the 5xx alerting fired on a daemon that was
    /// working exactly as configured.
    #[tokio::test]
    async fn spine_ingest_refuses_an_unserved_repo_id_rather_than_reporting_a_fault() {
        let advertised = "primary-repo";
        let sibling = "sibling-repo";
        let unserved = "unconfigured-repo";
        let (state, _faults) =
            hosted_state_with_allowlist("ingest-unserved", advertised, &[sibling]);
        assert!(
            !state.serves_repo_id(unserved),
            "the fixture must exclude the id under test from the served key space"
        );

        let (status, body) = spine_ingest(Arc::clone(&state), unserved).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::NOT_FOUND,
            "an id outside the served key space is a mis-addressed request, \
             not a daemon that failed: {message}"
        );
        assert!(
            message.contains(advertised) && message.contains(unserved),
            "the refusal must name the served and the requested id so the caller \
             can tell a typo from the wrong pod: {message}"
        );

        // An allowlisted sibling storage has never held is the other 404, and
        // the two must stay tellable apart in the body. Both are "not here",
        // but one says this pod does not own the repository and the other says
        // this pod owns it and has not ingested it, and those route to
        // different fixes: re-address the request, or run the ingest.
        assert!(
            message.contains("does not serve"),
            "the unserved refusal must say so plainly: {message}"
        );
        let (sibling_status, sibling_body) = spine_ingest(Arc::clone(&state), sibling).await;
        let sibling_message = String::from_utf8_lossy(&sibling_body);
        assert_eq!(
            sibling_status,
            StatusCode::NOT_FOUND,
            "a served sibling absent from storage is also missing: {sibling_message}"
        );
        assert!(
            !sibling_message.contains("does not serve"),
            "a served sibling must not inherit the unserved refusal: {sibling_message}"
        );
    }

    /// Absence and fault stay distinguishable on the ingest route too. A
    /// repository the allowlist admits but storage has never held is missing,
    /// and a backend that cannot answer for that same id is still a fault: the
    /// answer is decided by what the load reported, never by the id.
    #[tokio::test]
    async fn spine_ingest_reports_a_served_repo_absent_from_storage_as_missing() {
        let advertised = "primary-repo";
        let absent = "never-stored-repo";
        let (state, faults) = hosted_state_with_allowlist("ingest-absent", advertised, &[absent]);
        assert!(
            state.serves_repo_id(absent),
            "the allowlist is the served key space, so the absent id is served"
        );

        let (status, body) = spine_ingest(Arc::clone(&state), absent).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::NOT_FOUND,
            "a served repository storage does not hold is missing, not a fault: {message}"
        );
        assert!(
            !message.contains("does not serve"),
            "an allowlisted repository must not be reported as unserved: {message}"
        );

        faults.start_faulting(absent);
        let (status, body) = spine_ingest(Arc::clone(&state), absent).await;
        let message = String::from_utf8_lossy(&body);
        assert_eq!(
            status,
            StatusCode::INTERNAL_SERVER_ERROR,
            "a backend that cannot answer is still a fault: {message}"
        );
        assert!(
            message.contains(BACKEND_FAULT_TEXT),
            "the fault must carry the backend error rather than discard it: {message}"
        );
    }

    /// Discarding the user's whole vector index is a degradation, and a
    /// degradation nobody can read is indistinguishable from silence. The graph
    /// still serves every query, so this is not a fault; it is minutes to hours
    /// of embedding about to be paid for twice, and `/health` says so.
    #[cfg(feature = "vector")]
    #[tokio::test]
    async fn health_surfaces_a_discarded_vector_index_as_attention() {
        install_test_registry_override();
        let dir = std::env::temp_dir().join(format!("kin-daemon-kvec-discard-{}", Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        let layout = kin_core::init(&dir).unwrap().layout;
        // An index on disk that this build cannot bind to graph truth: the
        // shape every rejected sidecar arrives in, whatever rejected it.
        std::fs::create_dir_all(layout.kindb_dir()).unwrap();
        std::fs::write(layout.kindb_vector_index_path(), b"unbindable index").unwrap();
        let state = Arc::new(DaemonState::open(layout).unwrap());

        let response = router(state)
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let json: HealthResponse = serde_json::from_slice(&body).unwrap();

        let reason = json
            .vector_index_discarded
            .expect("a discarded index must be reported, not left to a coverage counter");
        assert!(
            reason.contains("graph.kvec"),
            "the report must name what was discarded: {reason}"
        );
        assert_eq!(
            json.status, "attention",
            "re-deriving the whole index is not an `ok` steady state"
        );
        assert!(
            !json.embed_worker_failed,
            "a discarded index is not a worker crash"
        );
    }

    #[tokio::test]
    async fn hosted_health_surfaces_embed_persistence_unavailable_attention() {
        let dir = std::env::temp_dir().join(format!("kin-daemon-hosted-health-{}", Uuid::new_v4()));
        let kin_dir = dir.join(".kin");
        std::fs::create_dir_all(kin_dir.join("objects")).unwrap();
        std::fs::create_dir_all(kin_dir.join("working")).unwrap();
        let layout = kin_core::KinLayout::new(kin_dir);
        kin_core::manifest::KinManifest::new()
            .save(&layout.manifest_path())
            .unwrap();
        let backend_dir = dir.join("backend");
        std::fs::create_dir_all(&backend_dir).unwrap();
        let state = Arc::new(
            DaemonState::open_with_backend(
                layout,
                Box::new(kin_db::LocalFileBackend::new(&backend_dir)),
                "hosted-health",
                None,
            )
            .unwrap(),
        );

        let response = router(state)
            .oneshot(Request::get("/health").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let json: HealthResponse = serde_json::from_slice(&body).unwrap();
        assert_eq!(json.status, "attention");
        assert!(json.embed_persistence_unavailable);
        assert!(
            json.filesystem_reconcile_disabled,
            "StorageBackend authority must intrinsically disable filesystem ingestion"
        );
        assert!(
            !json.embed_worker_failed,
            "unsupported persistence is a capability degradation, not a worker crash"
        );
    }

    #[tokio::test]
    async fn graph_only_command_commit_fails_before_filesystem_delta_computation() {
        let state = test_state();
        state
            .graph
            .upsert_entity(&test_entity("remote_authority", "src/remote.rs"))
            .unwrap();
        state
            .filesystem_reconcile_disabled
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let root_before = state.graph.compute_root_hash();
        let snapshot_before = state.graph.to_snapshot().to_bytes().unwrap();
        let generation_before = state
            .snapshot_generation
            .load(std::sync::atomic::Ordering::Relaxed);

        let response = router(Arc::clone(&state))
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "must not infer emptyDir removals"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);
        let body = axum::body::to_bytes(response.into_body(), 4096)
            .await
            .unwrap();
        let json: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(json["error"], "filesystem_admission_disabled");
        assert_eq!(json["endpoint"], "/commands/commit");
        assert_eq!(json["mutation_applied"], false);
        assert_eq!(state.graph.compute_root_hash(), root_before);
        assert_eq!(
            state.graph.to_snapshot().to_bytes().unwrap(),
            snapshot_before
        );
        assert_eq!(
            state
                .snapshot_generation
                .load(std::sync::atomic::Ordering::Relaxed),
            generation_before
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn command_commit_preserves_complete_arbitrary_repository_tree() {
        use kin_model::RepositoryAuthorityStore as _;
        use std::os::unix::fs::{symlink, PermissionsExt as _};

        let state = test_state();
        let root = state.layout.working_dir();
        std::fs::create_dir_all(root.join("assets")).unwrap();
        std::fs::write(
            root.join("compose.yaml"),
            b"services:\n  app:\n    image: kin:test\n",
        )
        .unwrap();
        std::fs::write(root.join("Dockerfile"), b"FROM scratch\n").unwrap();
        let mut executable = std::fs::metadata(root.join("Dockerfile"))
            .unwrap()
            .permissions();
        executable.set_mode(0o755);
        std::fs::set_permissions(root.join("Dockerfile"), executable).unwrap();
        std::fs::write(root.join("assets/model.bin"), [0, 0xff, 0x41, 0]).unwrap();
        std::fs::write(
            root.join("deployment.kin-unknown"),
            b"opaque=still-repository-truth\n",
        )
        .unwrap();
        symlink("compose.yaml", root.join("current-compose")).unwrap();

        let generation_before = ActiveApiRepositoryAuthority::open(&state)
            .unwrap()
            .manager
            .read_authority()
            .roots()
            .generation;
        let app = router(Arc::clone(&state));
        let obsolete_dry_run = app
            .clone()
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "obsolete dry run must not commit",
                            "dry_run": true
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(obsolete_dry_run.status(), StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(
            ActiveApiRepositoryAuthority::open(&state)
                .unwrap()
                .manager
                .read_authority()
                .roots()
                .generation,
            generation_before,
            "removed dry-run payload must fail before filesystem admission"
        );

        let response = app
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": kin_model::OperationId::new(),
                            "timestamp": kin_model::Timestamp::now(),
                            "message": "commit the complete arbitrary repository"
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let response: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(response["file_count"], 5);
        let change_id = kin_model::SemanticChangeId::from_hash(
            Hash256::from_hex(response["change_id"].as_str().unwrap()).unwrap(),
        );

        let authority = ActiveApiRepositoryAuthority::open(&state).unwrap();
        let lease = authority.manager.read_authority();
        let workspace = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap();
        assert_eq!(workspace.tree.len(), 5);
        assert_eq!(workspace.tree, state.graph.resolved_tree());
        assert_eq!(
            workspace
                .tree
                .artifact_at_path(&RepoPath::from_utf8("Dockerfile").unwrap())
                .unwrap()
                .entry,
            TreeEntry::blob(
                Hash256::from_bytes(kin_blobs::digest_bytes(b"FROM scratch\n")),
                true
            )
        );
        assert!(matches!(
            workspace
                .tree
                .artifact_at_path(&RepoPath::from_utf8("current-compose").unwrap())
                .unwrap()
                .entry,
            TreeEntry::Symlink { .. }
        ));
        assert_eq!(
            authority
                .manager
                .get_repository_ref(
                    &authority.repository_id,
                    lease.metadata().ref_state.default_ref.as_ref().unwrap(),
                )
                .unwrap()
                .unwrap()
                .target,
            kin_model::RefTarget::change(change_id)
        );
        assert!(lease
            .snapshot()
            .changes
            .iter()
            .any(|(_, change)| change.id == change_id));
    }

    async fn commit_through_api(
        app: &axum::Router,
        operation_id: kin_model::OperationId,
        message: &str,
    ) -> SemanticChangeId {
        let response = app
            .clone()
            .oneshot(
                Request::post("/commands/commit")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "operation_id": operation_id,
                            "timestamp": Timestamp::now(),
                            "message": message
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        let response: serde_json::Value = serde_json::from_slice(&body).unwrap();
        SemanticChangeId::from_hash(
            Hash256::from_hex(response["change_id"].as_str().unwrap()).unwrap(),
        )
    }

    async fn rollback_through_api(
        app: &axum::Router,
        operation_id: kin_model::OperationId,
        change_id: SemanticChangeId,
    ) -> (StatusCode, String) {
        let response = app
            .clone()
            .oneshot(
                Request::post("/commands/rollback")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "change_id": change_id.to_string(),
                            "operation_id": operation_id,
                            "actor": AuthorId::new("rollback-acceptance")
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        (status, String::from_utf8_lossy(&body).to_string())
    }

    async fn purge_ignored_through_api(
        app: &axum::Router,
        confirm: bool,
    ) -> (StatusCode, serde_json::Value) {
        let response = app
            .clone()
            .oneshot(
                Request::post("/commands/purge-ignored")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        json!({
                            "confirm": confirm,
                            "confirm_mass_deletion": true,
                            "operation_id": kin_model::OperationId::new(),
                            "actor": AuthorId::new("purge-acceptance")
                        })
                        .to_string(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        assert_eq!(status, StatusCode::OK, "{}", String::from_utf8_lossy(&body));
        (status, serde_json::from_slice(&body).unwrap())
    }

    fn tracked_paths(state: &DaemonState) -> std::collections::BTreeSet<String> {
        state
            .graph
            .resolved_tree()
            .artifacts_by_path()
            .map(|artifact| artifact.path.to_string())
            .collect()
    }

    /// A default exclude alone retires nothing, because ignore rules never hide
    /// tracked identity. The purge is what retires the backlog, and the removal
    /// has to be in authority rather than only in the live graph.
    #[tokio::test]
    async fn purge_ignored_untracks_admitted_derived_output_and_survives_restart() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let layout = state.layout.clone();

        for (path, content) in [
            ("src/lib.rs", &b"pub fn kept() {}"[..]),
            ("target/debug/app.o", &b"derived"[..]),
            ("target/debug/deps/lib.rlib", &b"derived"[..]),
        ] {
            install_working_copy_file(&state, path, content, false);
            install_repository_file(&state, path, content);
        }
        let app = router(Arc::clone(&state));

        // Precondition: the derived output really is tracked, so the assertions
        // below cannot pass because it was never admitted.
        assert!(tracked_paths(&state).contains("target/debug/app.o"));

        let (_, dry) = purge_ignored_through_api(&app, false).await;
        assert_eq!(dry["mutated"], json!(false));
        assert_eq!(dry["report"]["purge_count"], json!(2));
        assert_eq!(dry["report"]["tracked_total"], json!(3));
        assert_eq!(dry["report"]["retained_total"], json!(1));
        assert_eq!(dry["report"]["applied"], json!(false));
        assert_eq!(dry["report"]["kinignore_present"], json!(false));
        assert_eq!(
            dry["report"]["sample_paths"],
            json!(["target/debug/app.o", "target/debug/deps/lib.rlib"])
        );
        assert!(
            tracked_paths(&state).contains("target/debug/app.o"),
            "a dry run untracked a path"
        );

        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["mutated"], json!(true));
        assert_eq!(applied["report"]["applied"], json!(true));
        assert_eq!(applied["report"]["purge_count"], json!(2));
        assert!(applied["report"]["authority_generation"].is_number());

        let live = tracked_paths(&state);
        assert!(live.contains("src/lib.rs"));
        assert!(!live.contains("target/debug/app.o"));
        assert!(!live.contains("target/debug/deps/lib.rlib"));

        // The files are still on disk. Only tracking was retired.
        assert!(layout.working_dir().join("target/debug/app.o").exists());

        // Restart: a fresh daemon rebuilds its graph from persisted authority,
        // so this fails if the purge only moved the in-memory view.
        drop(app);
        drop(state);
        let restarted = Arc::new(DaemonState::open(layout).unwrap());
        let after_restart = tracked_paths(&restarted);
        assert!(after_restart.contains("src/lib.rs"));
        assert!(
            !after_restart.contains("target/debug/app.o"),
            "the purge did not survive a restart: {after_restart:?}"
        );
        assert!(!after_restart.contains("target/debug/deps/lib.rlib"));
    }

    /// A repository that states `!target` keeps its build output tracked, so the
    /// purge set is driven by the repository's rules and not by a hardcoded list.
    #[tokio::test]
    async fn purge_ignored_honors_a_readmitted_default() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        install_working_copy_file(&state, ".kinignore", b"!target\n", false);
        install_repository_file(&state, ".kinignore", b"!target\n");
        install_working_copy_file(&state, "target/debug/app.o", b"derived", false);
        install_repository_file(&state, "target/debug/app.o", b"derived");
        let app = router(Arc::clone(&state));

        let (_, dry) = purge_ignored_through_api(&app, false).await;
        assert_eq!(dry["report"]["purge_count"], json!(0));
        assert_eq!(dry["report"]["kinignore_present"], json!(true));
        assert!(dry["lines"]
            .as_array()
            .unwrap()
            .iter()
            .any(|line| line.as_str().unwrap().contains("Nothing to purge.")));

        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["mutated"], json!(false));
        assert!(tracked_paths(&state).contains("target/debug/app.o"));
    }

    /// Untracking is not enough. Entities are what rank, so a purge that left
    /// them behind produced the worst reading of all: the artifact listing no
    /// longer names the file while search and locate still return it.
    #[tokio::test]
    async fn purge_ignored_evicts_the_entities_that_made_a_path_rank() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        // The rule lands after the admission, which is the whole scenario: a
        // repository that already carries a path is told to stop carrying it.
        for (path, content) in [
            (
                "investor/deck/build_deck.py",
                &b"def valuation(): pass\n"[..],
            ),
            ("src/lib.py", &b"def kept(): pass\n"[..]),
            (".kinignore", &b"investor\n"[..]),
        ] {
            install_working_copy_file(&state, path, content, false);
            install_repository_file(&state, path, content);
        }

        let private = test_entity("valuation", "investor/deck/build_deck.py");
        let kept = test_entity("kept", "src/lib.py");
        state.graph.upsert_entity(&private).unwrap();
        state.graph.upsert_entity(&kept).unwrap();
        assert!(state.graph.get_entity(&private.id).unwrap().is_some());

        let app = router(Arc::clone(&state));
        let (_, applied) = purge_ignored_through_api(&app, true).await;
        assert_eq!(applied["report"]["purge_count"], json!(1));

        let live = tracked_paths(&state);
        assert!(!live.contains("investor/deck/build_deck.py"));
        assert!(
            state.graph.get_entity(&private.id).unwrap().is_none(),
            "a purged path's entity still resolves, so it still ranks"
        );
        assert!(state
            .graph
            .query_entities(&kin_db::EntityFilter {
                file_path: Some(kin_model::FilePathId::new("investor/deck/build_deck.py")),
                ..Default::default()
            })
            .unwrap()
            .is_empty());

        // The two-sided arm: an unnamed sibling keeps both its artifact and its
        // entity, so the purge removed one path rather than clearing the graph.
        assert!(live.contains("src/lib.py"));
        assert_eq!(state.graph.get_entity(&kept.id).unwrap(), Some(kept));
    }

    fn branch_change(state: &DaemonState) -> SemanticChangeId {
        let authority = ActiveApiRepositoryAuthority::open(state).unwrap();
        let lease = authority.manager.read_authority();
        let target = lease
            .metadata()
            .workspaces
            .iter()
            .find(|workspace| workspace.workspace_id == authority.workspace_id)
            .unwrap()
            .base_target
            .clone()
            .unwrap();
        lease.resolve_target_change_id(&target).unwrap()
    }

    /// An operation id is matched before any history validation runs, and an
    /// ordinary commit publishes the same receipt shape a rollback does. Only
    /// the restored content separates them, so reusing a commit's operation id
    /// must be refused instead of reported as a rollback that never happened.
    #[tokio::test]
    async fn command_rollback_refuses_an_operation_id_that_published_a_different_change() {
        let state = test_state();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let root = state.layout.working_dir().to_path_buf();
        let app = router(Arc::clone(&state));

        std::fs::write(root.join("service.txt"), b"shipped\n").unwrap();
        let restored = commit_through_api(
            &app,
            kin_model::OperationId::new(),
            "publish the good state",
        )
        .await;
        std::fs::write(root.join("service.txt"), b"regressed\n").unwrap();
        let reused = kin_model::OperationId::new();
        let regression = commit_through_api(&app, reused, "publish the regression").await;
        assert_eq!(branch_change(&state), regression);

        // The retained receipt for `reused` is an ordinary commit's. It carries
        // one ref mutation onto a change under a MustEqual expectation and a
        // workspace mutation, so every shape check passes; only the restored
        // content refutes it.
        let (status, body) = rollback_through_api(&app, reused, restored).await;
        assert_eq!(
            status,
            StatusCode::CONFLICT,
            "a commit's receipt was reported as this caller's rollback: {body}"
        );
        assert_eq!(
            branch_change(&state),
            regression,
            "a refused rollback moved the branch"
        );
        assert_eq!(
            std::fs::read(root.join("service.txt")).unwrap(),
            b"regressed\n",
            "a refused rollback restored the working copy anyway"
        );

        // The same reuse against a change this repository never materialized is
        // refused for the same reason: the echoed target is never trusted.
        let (status, body) = rollback_through_api(
            &app,
            reused,
            SemanticChangeId::from_hash(Hash256::from_bytes([0; 32])),
        )
        .await;
        assert_eq!(
            status,
            StatusCode::CONFLICT,
            "a rollback reported a target this repository does not have: {body}"
        );

        // Honest idempotency still reports success: a genuine rollback retried
        // with its own operation id reports what it published and commits
        // nothing further.
        let rollback_operation = kin_model::OperationId::new();
        let (status, body) = rollback_through_api(&app, rollback_operation, restored).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let first: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(first["mutated"], true);
        assert_eq!(first["report"]["target_change_id"], restored.to_string());
        let published = branch_change(&state);
        assert_ne!(published, regression, "rollback published no change");

        let (status, body) = rollback_through_api(&app, rollback_operation, restored).await;
        assert_eq!(status, StatusCode::OK, "{body}");
        let replay: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(
            replay["mutated"], false,
            "an already-published rollback committed a second change"
        );
        assert_eq!(replay["report"]["idempotent"], true);
        assert_eq!(replay["report"]["target_change_id"], restored.to_string());
        assert_eq!(
            replay["report"]["inverse_change_id"], first["report"]["inverse_change_id"],
            "the replay reported a different published change"
        );
        assert_eq!(
            branch_change(&state),
            published,
            "an already-published rollback moved the branch again"
        );
        assert_eq!(
            std::fs::read(root.join("service.txt")).unwrap(),
            b"shipped\n",
            "the rollback did not leave the restored content in place"
        );
    }

