    #[tokio::test]
    async fn mcp_transaction_commit_lands_relation_in_repository_authority() {
        // End-to-end: begin → stage → commit across separate calls must publish
        // the relation through repository authority and then derive the live
        // query graph from that committed state.
        let state = test_state();
        let mut caller = test_entity("caller", "src/lib.rs");
        caller.file_origin = None;
        caller.span = None;
        let mut callee = test_entity("callee", "src/lib.rs");
        callee.file_origin = None;
        callee.span = None;
        install_repository_entities(&state, vec![caller.clone(), callee.clone()]);
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let before = state.graph.relation_count();
        let session_id = mcp_test_session(&state);

        let begin = mcp_call(
            router(Arc::clone(&state)),
            "kin_transaction_begin",
            serde_json::json!({ "session_id": session_id, "scope": "file:src/lib.rs" }),
        )
        .await;
        let begin_json: serde_json::Value = serde_json::from_str(&mcp_result_text(&begin)).unwrap();
        let tx_id = begin_json["transaction_id"].as_str().unwrap().to_string();

        let _stage = mcp_call(
            router(Arc::clone(&state)),
            "kin_transaction_stage",
            serde_json::json!({
                "transaction_id": tx_id,
                "operations": [{
                    "verb": "add",
                    "target": "",
                    "payload": {
                        "Relation": {
                            "from": caller.id,
                            "to": callee.id,
                            "kind": RelationKind::Calls
                        }
                    },
                    "description": ""
                }]
            }),
        )
        .await;

        let commit = mcp_call(
            router(Arc::clone(&state)),
            "kin_transaction_commit",
            serde_json::json!({ "transaction_id": tx_id }),
        )
        .await;
        assert_ne!(
            commit.is_error,
            Some(true),
            "commit failed: {}",
            mcp_result_text(&commit)
        );

        assert_eq!(
            state.graph.relation_count(),
            before + 1,
            "committed relation must land in the canonical graph"
        );
        let authority = crate::repository_commit::load_native_commit_base(
            &crate::local_repository_authority::LocalRepositoryAuthorityContext::from_state(&state)
                .unwrap(),
        )
        .unwrap();
        assert_eq!(
            authority.graph.relation_count(),
            state.graph.relation_count()
        );
    }

    #[tokio::test]
    async fn mcp_transaction_enforce_rejects_before_repository_apply_and_records_event() {
        let state = test_state();
        *state
            .coordination_mode
            .write()
            .unwrap_or_else(std::sync::PoisonError::into_inner) =
            kin_mcp::CoordinationEnforcementMode::Enforce;
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let capabilities = SessionCapabilities {
            can_write: true,
            can_commit: true,
            ..SessionCapabilities::default()
        };
        let owner = state
            .coordinator
            .register_session(
                "claude-code",
                "owner",
                SessionTransport::Mcp,
                None,
                state.layout.working_dir().to_path_buf(),
                capabilities.clone(),
            )
            .unwrap();
        let caller = state
            .coordinator
            .register_session(
                "codex",
                "caller",
                SessionTransport::Mcp,
                None,
                state.layout.working_dir().to_path_buf(),
                capabilities,
            )
            .unwrap();
        let entity = test_entity("blocked_fn", "src/lib.rs");
        let registration = state
            .coordinator
            .register_intent(
                &owner,
                vec![IntentScope::Entity(entity.id)],
                LockType::Hard,
                "exclusive edit",
                None,
            )
            .unwrap();
        assert!(matches!(
            registration,
            crate::session_registry::IntentRegistrationResult::Registered { .. }
        ));
        let before = state.graph.entity_count();

        let begin = mcp_call_as(
            router(Arc::clone(&state)),
            "kin_transaction_begin",
            serde_json::json!({
                "session_id": caller.to_string(),
                "scope": "file:src/lib.rs"
            }),
            caller,
        )
        .await;
        let begin_json: serde_json::Value = serde_json::from_str(&mcp_result_text(&begin)).unwrap();
        let tx_id = begin_json["transaction_id"].as_str().unwrap().to_string();
        let stage = mcp_call_as(
            router(Arc::clone(&state)),
            "kin_transaction_stage",
            serde_json::json!({
                "transaction_id": tx_id,
                "operations": [{
                    "verb": "create",
                    "target": "",
                    "payload": { "Entity": entity },
                    "description": "must be vetoed"
                }]
            }),
            caller,
        )
        .await;
        assert_ne!(stage.is_error, Some(true));

        let commit = mcp_call_as(
            router(Arc::clone(&state)),
            "kin_transaction_commit",
            serde_json::json!({ "transaction_id": tx_id }),
            caller,
        )
        .await;
        assert_eq!(commit.is_error, Some(true));
        assert!(mcp_result_text(&commit).contains("before repository publication"));
        assert_eq!(
            state.graph.entity_count(),
            before,
            "rejected transaction must not mutate graph truth"
        );

        let records = std::fs::read_to_string(state.coordination_events.path()).unwrap();
        let last: crate::state::CoordinationEventEnvelope =
            serde_json::from_str(records.lines().last().unwrap()).unwrap();
        assert_eq!(last.event, "transaction_outcome");
        assert_eq!(
            last.outcome,
            "coordination_rejected_before_repository_apply"
        );
        assert_eq!(last.transaction_id.as_deref(), Some(tx_id.as_str()));
        assert_eq!(last.session_id, Some(caller.to_string()));
        assert_eq!(last.enforcement_mode, "enforce");
        assert_eq!(last.blocking_intent_ids.len(), 1);
    }

