    fn spine_test_fingerprint() -> kin_model::SemanticFingerprint {
        let zero = kin_model::Hash256::from_bytes([0u8; 32]);
        kin_model::SemanticFingerprint {
            algorithm: kin_model::FingerprintAlgorithm::V1TreeSitter,
            ast_hash: zero,
            signature_hash: zero,
            behavior_hash: zero,
            equivalence_hash: kin_model::Hash256::from_bytes([0; 32]),
            stability_score: 1.0,
        }
    }

    fn spine_test_entry(repo_id: &str, entity: &kin_model::Entity) -> kin_spine::EntityEntry {
        kin_spine::EntityEntry {
            repo_id: repo_id.to_string(),
            entity_id: entity.id,
            name: entity.name.clone(),
            kind: entity.kind,
            signature: entity.signature.clone(),
            fingerprint: entity.fingerprint.clone(),
            file_path: entity.file_origin.as_ref().map(|path| path.0.clone()),
            role: Some(entity.role),
        }
    }

    fn spine_test_entry_with_id(
        repo_id: &str,
        entity_id: EntityId,
        name: &str,
    ) -> kin_spine::EntityEntry {
        kin_spine::EntityEntry {
            repo_id: repo_id.to_string(),
            entity_id,
            name: name.to_string(),
            kind: kin_model::EntityKind::Function,
            signature: format!("fn {name}()"),
            fingerprint: spine_test_fingerprint(),
            file_path: Some(format!("src/{name}.rs")),
            role: Some(kin_model::EntityRole::Source),
        }
    }

    fn parse_consumer_source(file_path: &str, source: &str) -> kin_index::FileParseData {
        let registry = kin_parser::AdapterRegistry::new();
        let ext = std::path::Path::new(file_path)
            .extension()
            .and_then(|e| e.to_str())
            .expect("file extension");
        let file_id = FilePathId::new(file_path);
        let bytes = source.as_bytes();
        let adapter = registry
            .get_by_extension_and_content(ext, bytes)
            .expect("language adapter for extension");
        let language = adapter.language_id();
        let tree = adapter.parse(bytes).expect("parse");
        let output = adapter.extract(&tree, bytes, &file_id).expect("extract");
        let entities = output
            .entities
            .into_iter()
            .map(|e| e.into_entity_with_source(language, &file_id, Some(bytes)))
            .collect();
        kin_index::FileParseData {
            file_path: file_path.to_string(),
            entities,
            relations: output.relations,
            imports: output.imports,
        }
    }

    fn link_admitted_consumer_files(
        files: &[kin_index::FileParseData],
    ) -> Vec<kin_model::Relation> {
        let artifact_ids: HashMap<String, kin_model::ArtifactId> = files
            .iter()
            .map(|file| (file.file_path.clone(), kin_model::ArtifactId::new()))
            .collect();
        kin_index::link_cross_file(files, &artifact_ids)
            .expect("consumer fixture paths were explicitly admitted")
    }

    /// The daemon's /spine/xref and /spine/impact serve real cross-repo edges
    /// materialized from a parsed + linked fixture through the production refresh
    /// path, and fail loud rather than return an empty impact.
    #[tokio::test]
    async fn spine_impact_and_xref_serve_real_cross_repo_fixture() {
        let provider_entity = test_entity("do_work", "src/lib.py");
        let do_work_id = provider_entity.id;
        let provider_entry = spine_test_entry("provider", &provider_entity);

        let consumer = parse_consumer_source(
            "src/app.rs",
            "use provider::do_work;\n\npub fn run_task() {\n    do_work();\n}\n",
        );
        let consumer_entities = consumer.entities.clone();
        let consumer_relations = link_admitted_consumer_files(&[consumer]);
        let run_task_id = consumer_entities
            .iter()
            .find(|e| e.name == "run_task")
            .expect("run_task entity present")
            .id;

        let state = test_state();
        let spine = state.ensure_spine().expect("spine enabled in test");
        spine.register_repo("provider", vec![provider_entry], "provider-root");
        spine.register_repo(
            "consumer",
            consumer_entities
                .iter()
                .map(|entity| spine_test_entry("consumer", entity))
                .collect(),
            "consumer-root",
        );
        let mut registry = spine.registered_repo_ids().into_iter().collect::<Vec<_>>();
        registry.sort();
        for repo in &registry {
            match repo.as_str() {
                "provider" => spine.refresh_cross_repo_edges(
                    repo,
                    std::slice::from_ref(&provider_entity),
                    &[],
                    &registry,
                ),
                "consumer" => spine.refresh_cross_repo_edges(
                    repo,
                    &consumer_entities,
                    &consumer_relations,
                    &registry,
                ),
                _ => spine.refresh_cross_repo_edges(repo, &[], &[], &registry),
            }
        }
        assert!(
            spine.edge_count() >= 1,
            "fixture must materialize a cross-repo edge (parse -> link -> spine)"
        );

        let app = router(state);

        let xref = app
            .clone()
            .oneshot(
                Request::get(format!(
                    "/spine/xref?repo=consumer&entity={}",
                    run_task_id.0
                ))
                .body(Body::empty())
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(xref.status(), StatusCode::OK);
        let xbody: serde_json::Value =
            serde_json::from_slice(&axum::body::to_bytes(xref.into_body(), 65536).await.unwrap())
                .unwrap();
        let edges = xbody["edges"]
            .as_array()
            .expect("edges array in /spine/xref");
        assert!(
            !edges.is_empty(),
            "/spine/xref must return the cross-repo edge, not an empty list"
        );
        assert!(
            edges.iter().any(|e| e["dst_repo"] == "provider"),
            "the cross-repo edge must resolve to the provider repo, got {edges:?}"
        );
        assert_eq!(
            xbody["version"],
            serde_json::json!(kin_spine::SPINE_PAYLOAD_VERSION),
            "/spine/xref payload must carry the spine wire-format version"
        );
        assert_eq!(xbody["authority_complete"], true);
        assert_eq!(xbody["authority_anchor"]["repo_id"], "consumer");
        assert_eq!(
            xbody["authority_anchor"]["entity_id"],
            serde_json::json!(run_task_id)
        );
        assert!(xbody["authority_revision"]
            .as_str()
            .is_some_and(|revision| revision.starts_with("sha256:") && revision.len() == 71));
        assert_eq!(xbody["authority_roots"]["consumer"], "consumer-root");
        assert_eq!(xbody["authority_roots"]["provider"], "provider-root");
        assert!(xbody["entities"].as_array().is_some_and(|entities| {
            entities.iter().any(|entity| entity["name"] == "run_task")
                && entities.iter().any(|entity| entity["name"] == "do_work")
        }));

        let snapshot = app
            .clone()
            .oneshot(Request::get("/spine/edges").body(Body::empty()).unwrap())
            .await
            .unwrap();
        assert_eq!(snapshot.status(), StatusCode::OK);
        let snapshot_body = axum::body::to_bytes(snapshot.into_body(), 65536)
            .await
            .unwrap();
        let snapshot_json: serde_json::Value = serde_json::from_slice(&snapshot_body).unwrap();
        assert_eq!(
            snapshot_json["version"],
            serde_json::json!(kin_spine::SPINE_PAYLOAD_VERSION)
        );
        assert_eq!(snapshot_json["complete"], true);
        assert!(snapshot_json["revision"]
            .as_str()
            .is_some_and(|revision| revision.starts_with("sha256:") && revision.len() == 71));
        assert!(snapshot_json["edges"]
            .as_array()
            .expect("bulk snapshot edges")
            .iter()
            .any(|edge| edge["src_repo"] == "consumer" && edge["dst_repo"] == "provider"));

        let impact = app
            .oneshot(
                Request::get(format!(
                    "/spine/impact?repo=provider&entity={}&depth=5",
                    do_work_id.0
                ))
                .body(Body::empty())
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(impact.status(), StatusCode::OK);
        let ibody: serde_json::Value = serde_json::from_slice(
            &axum::body::to_bytes(impact.into_body(), 65536)
                .await
                .unwrap(),
        )
        .unwrap();
        let repos: Vec<&str> = ibody["repos_involved"]
            .as_array()
            .expect("repos_involved array in /spine/impact")
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        assert!(
            repos.contains(&"consumer"),
            "federated impact of do_work must include the consumer repo (blast radius), got {repos:?}"
        );
        assert_eq!(
            ibody["version"],
            serde_json::json!(kin_spine::SPINE_PAYLOAD_VERSION),
            "/spine/impact payload must carry the spine wire-format version"
        );
    }

    #[tokio::test]
    async fn spine_xref_fails_closed_while_topology_is_dirty_then_exposes_complete_watermark() {
        let consumer_id = EntityId::new();
        let provider_id = EntityId::new();
        let state = test_state();
        let spine = state.ensure_spine().expect("spine enabled in test");
        spine.register_repo(
            "consumer",
            vec![spine_test_entry_with_id(
                "consumer",
                consumer_id,
                "run_task",
            )],
            "consumer-root",
        );
        spine.register_repo(
            "provider",
            vec![spine_test_entry_with_id("provider", provider_id, "do_work")],
            "provider-root",
        );
        spine.add_cross_repo_edge(kin_spine::CrossRepoEdge {
            src_repo: "consumer".to_string(),
            src_entity: consumer_id,
            dst_repo: "provider".to_string(),
            dst_entity: provider_id,
            confidence: 0.9,
        });

        let app = router(state.clone());
        let read_xref = |app: Router| async move {
            let response = app
                .oneshot(
                    Request::get(format!(
                        "/spine/xref?repo=provider&entity={}",
                        provider_id.0
                    ))
                    .body(Body::empty())
                    .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            serde_json::from_slice::<serde_json::Value>(
                &axum::body::to_bytes(response.into_body(), 65536)
                    .await
                    .unwrap(),
            )
            .unwrap()
        };

        let dirty = read_xref(app.clone()).await;
        assert_eq!(dirty["authority_complete"], false);
        assert!(dirty["authority_revision"]
            .as_str()
            .is_some_and(|revision| revision.starts_with("sha256:")));
        assert_eq!(dirty["authority_roots"]["provider"], "provider-root");
        assert_eq!(dirty["edges"].as_array().map(Vec::len), Some(1));
        assert_eq!(dirty["entities"].as_array().map(Vec::len), Some(2));

        let mut repos = state
            .ensure_spine()
            .expect("spine enabled in test")
            .registered_repo_ids()
            .into_iter()
            .collect::<Vec<_>>();
        repos.sort();
        for repo in &repos {
            state
                .ensure_spine()
                .expect("spine enabled in test")
                .refresh_cross_repo_edges(repo, &[], &[], &repos);
        }
        let complete = read_xref(app).await;
        assert_eq!(complete["authority_complete"], true);
        assert_eq!(complete["authority_roots"], dirty["authority_roots"]);
        assert_ne!(complete["authority_revision"], dirty["authority_revision"]);
        assert!(complete["edges"].as_array().is_some_and(Vec::is_empty));
    }

    #[tokio::test]
    async fn spine_edges_snapshot_is_stable_deduped_and_never_reads_source_files() {
        let state = test_state();
        let spine = state.ensure_spine().expect("spine enabled in test");
        let alpha = EntityId::from_content("src/a.rs", "alpha", "function", 1);
        let beta = EntityId::from_content("src/b.rs", "beta", "function", 1);
        let gamma = EntityId::from_content("src/c.rs", "gamma", "function", 1);
        spine.register_repo(
            "alpha",
            vec![spine_test_entry_with_id("alpha", alpha, "alpha")],
            "root-a",
        );
        spine.register_repo(
            "beta",
            vec![spine_test_entry_with_id("beta", beta, "beta")],
            "root-b",
        );
        spine.register_repo(
            "gamma",
            vec![spine_test_entry_with_id("gamma", gamma, "gamma")],
            "root-c",
        );
        let mut registry = spine.registered_repo_ids().into_iter().collect::<Vec<_>>();
        registry.sort();
        for repo in &registry {
            spine.refresh_cross_repo_edges(repo, &[], &[], &registry);
        }

        let first_edge = kin_spine::CrossRepoEdge {
            src_repo: "alpha".to_string(),
            src_entity: alpha,
            dst_repo: "beta".to_string(),
            dst_entity: beta,
            confidence: 0.9,
        };
        let second_edge = kin_spine::CrossRepoEdge {
            src_repo: "beta".to_string(),
            src_entity: beta,
            dst_repo: "gamma".to_string(),
            dst_entity: gamma,
            confidence: 0.8,
        };
        spine.add_cross_repo_edge(second_edge);
        spine.add_cross_repo_edge(first_edge.clone());
        spine.add_cross_repo_edge(kin_spine::CrossRepoEdge {
            confidence: 0.2,
            ..first_edge.clone()
        });
        spine.add_cross_repo_edge(first_edge);

        let workspace = state.layout.working_dir().to_path_buf();
        let app = router(state);
        let read_snapshot = |app: Router| async move {
            let response = app
                .oneshot(Request::get("/spine/edges").body(Body::empty()).unwrap())
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            axum::body::to_bytes(response.into_body(), 65536)
                .await
                .unwrap()
        };

        let before = read_snapshot(app.clone()).await;
        let repeated = read_snapshot(app.clone()).await;
        assert_eq!(
            before, repeated,
            "unchanged authority must return stable bytes"
        );

        let json: serde_json::Value = serde_json::from_slice(&before).unwrap();
        let edges = json["edges"].as_array().expect("snapshot edges");
        assert_eq!(edges.len(), 2, "topology-duplicate edges must collapse");
        assert_eq!(edges[0]["src_repo"], "alpha");
        assert_eq!(edges[0]["confidence"], 0.9);
        assert_eq!(edges[1]["src_repo"], "beta");
        assert_eq!(json["complete"], true);

        // A raw source file that names another repo must not affect this graph
        // authority read. If the route walked/searched files as a fallback,
        // either its bytes or revision would change here.
        let source_dir = workspace.join("src");
        std::fs::create_dir_all(&source_dir).unwrap();
        std::fs::write(
            source_dir.join("decoy.rs"),
            "use unregistered::phantom; pub fn decoy() { phantom(); }\n",
        )
        .unwrap();
        let after_decoy = read_snapshot(app).await;
        assert_eq!(
            before, after_decoy,
            "bulk spine snapshot must never fall back to raw file search"
        );
    }

    /// The daemon's /spine endpoints serve a TRANSITIVE (2-hop) blast radius and
    /// MULTI-CONSUMER edges through the production refresh path: provider <-
    /// consumer <- downstream, plus a second consumer of provider. This is the
    /// transitive/multi-consumer gate on top of the 1-hop fixture; it
    /// depends on refresh registering each repo's own entities so the next hop
    /// can resolve them.
    #[tokio::test]
    async fn spine_serves_transitive_2hop_and_multi_consumer_blast_radius() {
        let do_work_id = EntityId::new();
        let provider_entry = kin_spine::EntityEntry {
            repo_id: "provider".to_string(),
            entity_id: do_work_id,
            name: "do_work".to_string(),
            kind: kin_model::EntityKind::Function,
            signature: "fn do_work()".to_string(),
            fingerprint: spine_test_fingerprint(),
            file_path: Some("src/lib.rs".to_string()),
            role: Some(kin_model::EntityRole::Source),
        };

        // consumer: imports provider::do_work via run_task (the 1st hop).
        let consumer = parse_consumer_source(
            "src/app.rs",
            "use provider::do_work;\n\npub fn run_task() {\n    do_work();\n}\n",
        );
        let consumer_entities = consumer.entities.clone();
        let consumer_relations = link_admitted_consumer_files(&[consumer]);
        let run_task_id = consumer_entities
            .iter()
            .find(|e| e.name == "run_task")
            .expect("run_task entity present")
            .id;

        // consumer2: a SECOND consumer of provider::do_work (multi-consumer).
        let consumer2 = parse_consumer_source(
            "src/other.rs",
            "use provider::do_work;\n\npub fn other_task() {\n    do_work();\n}\n",
        );
        let consumer2_entities = consumer2.entities.clone();
        let consumer2_relations = link_admitted_consumer_files(&[consumer2]);

        // downstream: imports consumer::run_task (the 2nd hop).
        let downstream = parse_consumer_source(
            "src/top.rs",
            "use consumer::run_task;\n\npub fn orchestrate() {\n    run_task();\n}\n",
        );
        let downstream_entities = downstream.entities.clone();
        let downstream_relations = link_admitted_consumer_files(&[downstream]);
        let orchestrate_id = downstream_entities
            .iter()
            .find(|e| e.name == "orchestrate")
            .expect("orchestrate entity present")
            .id;

        let state = test_state();
        let spine = state.ensure_spine().expect("spine enabled in test");
        let registry = [
            "provider".to_string(),
            "consumer".to_string(),
            "consumer2".to_string(),
            "downstream".to_string(),
        ];
        spine.register_repo("provider", vec![provider_entry], "");
        // Each refresh registers the repo's own entities as resolution targets so
        // the next hop can bind to them — the behavior this gate proves. Refresh
        // in dependency order so each hop's targets are present.
        spine.refresh_cross_repo_edges(
            "consumer",
            &consumer_entities,
            &consumer_relations,
            &registry,
        );
        spine.refresh_cross_repo_edges(
            "consumer2",
            &consumer2_entities,
            &consumer2_relations,
            &registry,
        );
        spine.refresh_cross_repo_edges(
            "downstream",
            &downstream_entities,
            &downstream_relations,
            &registry,
        );

        let app = router(state);

        // 2-hop: /spine/xref for downstream's orchestrate resolves into consumer.
        let xref = app
            .clone()
            .oneshot(
                Request::get(format!(
                    "/spine/xref?repo=downstream&entity={}",
                    orchestrate_id.0
                ))
                .body(Body::empty())
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(xref.status(), StatusCode::OK);
        let xbody: serde_json::Value =
            serde_json::from_slice(&axum::body::to_bytes(xref.into_body(), 65536).await.unwrap())
                .unwrap();
        let edges = xbody["edges"]
            .as_array()
            .expect("edges array in /spine/xref");
        assert!(
            edges.iter().any(|e| e["dst_repo"] == "consumer"),
            "2-hop: downstream must resolve a cross-repo edge into consumer, got {edges:?}"
        );

        // Multi-consumer + transitive: federated impact of provider::do_work
        // includes BOTH consumers AND the transitive downstream repo.
        let impact = app
            .oneshot(
                Request::get(format!(
                    "/spine/impact?repo=provider&entity={}&depth=5",
                    do_work_id.0
                ))
                .body(Body::empty())
                .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(impact.status(), StatusCode::OK);
        let ibody: serde_json::Value = serde_json::from_slice(
            &axum::body::to_bytes(impact.into_body(), 65536)
                .await
                .unwrap(),
        )
        .unwrap();
        let repos: Vec<&str> = ibody["repos_involved"]
            .as_array()
            .expect("repos_involved array in /spine/impact")
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        assert!(
            repos.contains(&"consumer") && repos.contains(&"consumer2"),
            "multi-consumer: both consumers must appear in provider's blast radius, got {repos:?}"
        );
        assert!(
            repos.contains(&"downstream"),
            "transitive: the 2-hop downstream repo must appear in provider's blast radius, got {repos:?}"
        );
        // Bind the 1st-hop id so the helper is exercised end-to-end (and the
        // unused-variable lint stays quiet) — run_task anchors the chain.
        let _ = run_task_id;
    }

    #[tokio::test]
    async fn spine_ingest_route_rejects_body_repo_mismatch() {
        // The path `repo_id` is authoritative. A body `repo` that disagrees is
        // an orchestrator wiring bug and must be refused before any ingest, so
        // a mis-wired client can never load the wrong repo into the spine.
        let state = test_state();
        let app = router(state);

        let response = app
            .oneshot(
                Request::post("/spine/repos/kin/ingest")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&serde_json::json!({
                            "repo": "kin-db",
                            "refreshCrossRepoEdges": true,
                        }))
                        .unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            response.status(),
            StatusCode::BAD_REQUEST,
            "a body repo that disagrees with the path repo_id must be rejected"
        );
        let body = String::from_utf8(
            axum::body::to_bytes(response.into_body(), 4096)
                .await
                .unwrap()
                .to_vec(),
        )
        .unwrap();
        assert!(
            body.contains("does not match"),
            "rejection must explain the path/body mismatch, got: {body}"
        );
    }

    #[tokio::test]
    async fn spine_ingest_route_requires_a_storage_backend() {
        // Without a configured StorageBackend (the local single-repo daemon),
        // the multi-repo ingest path has nowhere to load a repo's graph from and
        // must fail loud rather than silently serve an empty cross-repo graph.
        // The hosted pod always runs with a backend; this guards the misconfig.
        let state = test_state();
        let app = router(state);

        let response = app
            .oneshot(
                Request::post("/spine/repos/kin/ingest")
                    .header("content-type", "application/json")
                    .body(Body::from(
                        serde_json::to_vec(&serde_json::json!({ "repo": "kin" })).unwrap(),
                    ))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(
            response.status(),
            StatusCode::INTERNAL_SERVER_ERROR,
            "ingest without a storage backend must surface an error, not a 200"
        );
    }

    #[tokio::test]
    async fn spine_refresh_cross_repo_edges_route_is_wired_and_degrades_gracefully() {
        // The hosted orchestrator calls this final pass after every repo is
        // ingested so edges emanate from every repo, not just the anchor. Without
        // a storage backend (the local single-repo daemon) no repo graph can be
        // loaded, so the pass refreshes nothing — but it must still answer 200
        // with the camelCase contract the orchestrator reads, never a 500/panic.
        let state = test_state();
        let spine = state.ensure_spine().expect("spine enabled in test");
        // Register two repos' metadata so the pass has a non-empty repo set to
        // iterate over (their graphs are unavailable without a backend). The
        // daemon's own repo is also registered and remains loadable from its
        // in-process graph.
        spine.register_repo("kin", vec![], "kin-root");
        spine.register_repo("kin-db", vec![], "kin-db-root");
        let mut repos = spine.registered_repo_ids().into_iter().collect::<Vec<_>>();
        repos.sort();
        for repo in &repos {
            spine.refresh_cross_repo_edges(repo, &[], &[], &repos);
        }
        assert!(
            spine.cross_repo_edges_snapshot().complete,
            "fixture starts complete so skipped loads test invalidation"
        );
        let app = router(Arc::clone(&state));

        let response = app
            .oneshot(
                Request::post("/spine/refresh-cross-repo-edges")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(response.status(), StatusCode::OK);
        let body: serde_json::Value = serde_json::from_slice(
            &axum::body::to_bytes(response.into_body(), 4096)
                .await
                .unwrap(),
        )
        .unwrap();
        assert!(
            body.get("reposRefreshed").is_some(),
            "response must carry reposRefreshed, got {body}"
        );
        assert!(
            body.get("crossRepoEdges").is_some(),
            "response must carry crossRepoEdges, got {body}"
        );
        // No backend means the two foreign repo graphs are unavailable. The
        // two-phase pass must not certify a partial registry by refreshing only
        // the daemon's in-process repo, so zero repos are reported refreshed
        // and the prior complete watermark remains revoked.
        assert_eq!(body["reposRefreshed"], serde_json::json!(0));
        assert!(
            !state
                .ensure_spine()
                .expect("spine remains enabled")
                .cross_repo_edges_snapshot()
                .complete,
            "skipped registered repos must revoke the old complete watermark"
        );
    }

    /// One gate proving the cross-repo blast radius is consistent across every
    /// kin-side surface that consumes the spine — the daemon HTTP API, the
    /// `kin xref`/`kin impact` CLI client code, and the MCP impact_analysis
    /// client code — over a single real parsed+linked fixture served by a real
    /// daemon socket.
    ///
    /// Each surface runs its OWN production client (not a re-implementation):
    /// the daemon HTTP contract via reqwest (the same one KinLab's fetch path
    /// uses), `kin_cli::backend::get_spine_{xref,impact}` (what `kin xref` /
    /// `kin impact` call), and `kin_mcp::handlers::common::fetch_spine_{xref,
    /// impact_typed}` (what MCP impact_analysis calls). All three resolve the
    /// daemon through `KIN_DAEMON_URL`, so they hit this in-process daemon.
    ///
    /// The hosted KinLab surface and cloud/Firestore restart-hydration are out
    /// of scope for this in-process daemon test.
    #[tokio::test]
    #[serial_test::serial]
    async fn spine_blast_radius_is_consistent_across_daemon_cli_and_mcp() {
        use kin_cli::backend::{get_spine_impact, get_spine_xref};
        use kin_mcp::handlers::common::{fetch_spine_impact_typed, fetch_spine_xref};

        // The manifest-generated repository UUID is the local authority
        // identity. Human fixture labels such as "provider" must never
        // override or impersonate it.
        let state = test_state();
        let provider_repo_id = state.cached_repo_id.clone();

        // Fixture: provider exports do_work; consumer imports and calls it.
        let do_work_id = EntityId::new();
        let provider_entry = kin_spine::EntityEntry {
            repo_id: provider_repo_id.clone(),
            entity_id: do_work_id,
            name: "do_work".to_string(),
            kind: kin_model::EntityKind::Function,
            signature: "fn do_work()".to_string(),
            fingerprint: spine_test_fingerprint(),
            file_path: Some("src/lib.rs".to_string()),
            role: Some(kin_model::EntityRole::Source),
        };
        let consumer = parse_consumer_source(
            "src/app.rs",
            "use provider::do_work;\n\npub fn run_task() {\n    do_work();\n}\n",
        );
        let consumer_entities = consumer.entities.clone();
        let consumer_relations = link_admitted_consumer_files(&[consumer]);
        let run_task_id = consumer_entities
            .iter()
            .find(|e| e.name == "run_task")
            .expect("run_task entity present")
            .id;

        // Pin the daemon's canonical graph identity without mutating process
        // environment shared by concurrently executing tests.
        let mut provider_entity = test_entity("do_work", "src/lib.rs");
        provider_entity.id = do_work_id;
        state.graph.upsert_entity(&provider_entity).unwrap();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);
        let layout = state.layout.clone();
        let provider_root = hex::encode(state.graph.compute_root_hash());
        {
            let spine = state.ensure_spine().expect("spine enabled in test");
            spine.register_repo(&provider_repo_id, vec![provider_entry], &provider_root);
            spine.register_repo(
                "consumer",
                consumer_entities
                    .iter()
                    .map(|entity| spine_test_entry("consumer", entity))
                    .collect(),
                "consumer-root",
            );
            let mut registry = spine.registered_repo_ids().into_iter().collect::<Vec<_>>();
            registry.sort();
            for repo in &registry {
                match repo.as_str() {
                    "consumer" => spine.refresh_cross_repo_edges(
                        repo,
                        &consumer_entities,
                        &consumer_relations,
                        &registry,
                    ),
                    _ => spine.refresh_cross_repo_edges(repo, &[], &[], &registry),
                }
            }
            assert!(
                spine.edge_count() >= 1,
                "fixture must materialize a cross-repo edge (parse -> link -> spine)"
            );
        }

        // Serve the real daemon router on an ephemeral loopback socket.
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, router(state)).await;
        });
        let base = format!("http://{addr}");
        let mut daemon_url = kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", &base);

        let run_task_str = run_task_id.to_string();
        let do_work_str = do_work_id.to_string();

        // ── Surface 1: daemon HTTP (also the KinLab fetch contract). ──
        let http = reqwest::Client::new();
        let http_xref_response = http
            .get(format!("{base}/spine/xref"))
            .query(&[("repo", "consumer"), ("entity", run_task_str.as_str())])
            .send()
            .await
            .expect("daemon xref request");
        let http_xref_status = http_xref_response.status();
        let http_xref_bytes = http_xref_response.bytes().await.expect("daemon xref body");
        assert!(
            http_xref_status.is_success(),
            "daemon xref returned {http_xref_status}: {}",
            String::from_utf8_lossy(&http_xref_bytes)
        );
        let http_xref: serde_json::Value =
            serde_json::from_slice(&http_xref_bytes).expect("daemon xref json");
        let daemon_xref_to_provider = http_xref["edges"]
            .as_array()
            .map(|edges| {
                edges
                    .iter()
                    .any(|e| e["dst_repo"].as_str() == Some(provider_repo_id.as_str()))
            })
            .unwrap_or(false);
        assert!(
            daemon_xref_to_provider,
            "daemon /spine/xref must resolve the consumer->provider edge: {http_xref}"
        );

        let http_impact: serde_json::Value = http
            .get(format!("{base}/spine/impact"))
            .query(&[
                ("repo", provider_repo_id.as_str()),
                ("entity", do_work_str.as_str()),
                ("depth", "5"),
            ])
            .send()
            .await
            .expect("daemon impact request")
            .json()
            .await
            .expect("daemon impact json");
        let daemon_impact_hits_consumer = http_impact["repos_involved"]
            .as_array()
            .map(|repos| repos.iter().any(|r| r == "consumer"))
            .unwrap_or(false);
        assert!(
            daemon_impact_hits_consumer,
            "daemon /spine/impact blast radius must include consumer: {http_impact}"
        );

        // ── Surface 2: the `kin xref` / `kin impact` CLI client code. ──
        let cli_xref = match get_spine_xref(&layout, "consumer", &run_task_id)
            .await
            .expect("CLI get_spine_xref call")
        {
            kin_spine::SpineQuery::Found(response) => response,
            other => panic!("CLI get_spine_xref expected Found, got {other:?}"),
        };
        let cli_xref_to_provider = cli_xref
            .edges
            .iter()
            .any(|e| e.dst_repo == provider_repo_id);
        assert!(
            cli_xref_to_provider,
            "kin xref CLI must resolve consumer->provider: {cli_xref:?}"
        );

        let cli_impact = match get_spine_impact(&layout, &provider_repo_id, &do_work_id, 5)
            .await
            .expect("CLI get_spine_impact call")
        {
            kin_spine::SpineQuery::Found(impact) => impact,
            other => panic!("CLI get_spine_impact expected Found, got {other:?}"),
        };
        let cli_impact_hits_consumer = cli_impact.repos_involved.iter().any(|r| r == "consumer");
        assert!(
            cli_impact_hits_consumer,
            "kin impact CLI blast radius must include consumer: {:?}",
            cli_impact.repos_involved
        );

        // ── Surface 3: the MCP impact_analysis client code. ──
        let mcp_xref = match fetch_spine_xref("consumer", &run_task_id).await {
            kin_spine::SpineQuery::Found(body) => body,
            other => panic!("MCP fetch_spine_xref expected Found, got {other:?}"),
        };
        let mcp_xref_to_provider = mcp_xref
            .edges
            .iter()
            .any(|edge| edge.dst_repo == provider_repo_id);
        assert!(
            mcp_xref_to_provider,
            "MCP fetch_spine_xref must resolve consumer->provider: {mcp_xref:?}"
        );

        let mcp_impact = match fetch_spine_impact_typed(&provider_repo_id, &do_work_id, 5).await {
            kin_spine::SpineQuery::Found(impact) => impact,
            other => panic!("MCP fetch_spine_impact_typed expected Found, got {other:?}"),
        };
        let mcp_impact_hits_consumer = mcp_impact.repos_involved.iter().any(|r| r == "consumer");
        assert!(
            mcp_impact_hits_consumer,
            "MCP impact blast radius must include consumer: {:?}",
            mcp_impact.repos_involved
        );

        // ── Consistency: all three surfaces agree on the cross-repo result. ──
        assert_eq!(
            cli_impact.repos_involved.iter().any(|r| r == "consumer"),
            mcp_impact.repos_involved.iter().any(|r| r == "consumer"),
            "CLI and MCP must agree on the impacted repo set"
        );
        assert!(
            daemon_xref_to_provider && cli_xref_to_provider && mcp_xref_to_provider,
            "daemon, CLI, and MCP must all resolve the same consumer->provider xref"
        );

        // The agent-facing production route must project that real incoming
        // edge without looping back through KIN_DAEMON_URL. A foreign request
        // argument must not override DaemonState's repo binding.
        daemon_url.apply::<_, &str>("KIN_DAEMON_URL", None);
        let result: kin_mcp::ToolCallResult = http
            .post(format!("{base}/mcp/tools/call"))
            .json(&serde_json::json!({
                "name": "find_references",
                "arguments": {
                    "entity_id": do_work_id.to_string(),
                    "repo_id": "request-controlled",
                },
            }))
            .send()
            .await
            .expect("daemon MCP find_references request")
            .json()
            .await
            .expect("daemon MCP find_references response");
        let kin_mcp::types::ContentBlock::Text { text } = result
            .content
            .first()
            .expect("find_references text response");
        let body: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(body["cross_repo"]["status"], "available");
        assert_eq!(body["cross_repo"]["reference_count"], 1);
        assert_eq!(body["cross_repo"]["authority_complete"], true);
        assert_eq!(
            body["cross_repo"]["authority_anchor"]["repo_id"],
            provider_repo_id
        );
        assert!(body["cross_repo"]["authority_revision"]
            .as_str()
            .is_some_and(|revision| revision.starts_with("sha256:")));
        assert_eq!(
            body["cross_repo"]["authority_roots"][provider_repo_id.as_str()],
            provider_root
        );
        assert!(body["references"].as_array().is_some_and(|references| {
            references.iter().any(|reference| {
                reference["name"] == "run_task" && reference["file_path"] == "[consumer] src/app.rs"
            })
        }));

        server.abort();
    }

    #[tokio::test]
    async fn daemon_mcp_bulk_reachability_uses_exact_federated_authority() {
        let state = test_state();
        let provider_repo_id = state.cached_repo_id.clone();
        let target = test_entity("target", "src/lib.rs");
        let source = test_entity("caller", "src/app.rs");
        state.graph.upsert_entity(&target).unwrap();
        state
            .is_initialized
            .store(true, std::sync::atomic::Ordering::Relaxed);

        let spine = state.ensure_spine().expect("spine enabled in test");
        let provider_root = hex::encode(state.graph.compute_root_hash());
        assert_eq!(
            spine.root_hash(&provider_repo_id).as_deref(),
            Some(provider_root.as_str())
        );
        spine.register_repo(
            "consumer",
            vec![spine_test_entry("consumer", &source)],
            "consumer-root",
        );
        let mut repos = spine.registered_repo_ids().into_iter().collect::<Vec<_>>();
        repos.sort();
        for repo in &repos {
            spine.refresh_cross_repo_edges(repo, &[], &[], &repos);
        }
        spine.add_cross_repo_edge(kin_spine::CrossRepoEdge {
            src_repo: "consumer".to_string(),
            src_entity: source.id,
            dst_repo: provider_repo_id.clone(),
            dst_entity: target.id,
            confidence: 0.9,
        });

        let result = mcp_call(
            router(Arc::clone(&state)),
            "bulk_check_references",
            serde_json::json!({
                "entity_ids": [target.id.to_string()],
                "relation_kind": "Any",
            }),
        )
        .await;
        let result = kin_mcp::finalize_with_envelope(
            result,
            kin_mcp::Envelope::daemon().with_health(&serde_json::json!({
                "initialized": true,
                "graph_loaded": true,
                "graph_generation": 12,
            })),
            "bulk_check_references",
        );
        let body: serde_json::Value = serde_json::from_str(&mcp_result_text(&result)).unwrap();
        assert_eq!(body["results"][0]["has_references"], true);
        assert_eq!(body["results"][0]["federated_reference_count"], 1);
        assert_eq!(body["cross_repo"]["authority_complete"], true);
        assert_eq!(
            body["cross_repo"]["authority_roots"][provider_repo_id.as_str()],
            provider_root
        );
        assert_eq!(body["negative"]["safe_to_conclude_absent"], true);
    }

    #[tokio::test]
    async fn xref_reads_retry_when_head_mutates_between_root_and_read_even_after_aba() {
        let state = test_state();
        let provider_repo_id = state.cached_repo_id.clone();
        let target = test_entity("target", "src/lib.rs");
        state.graph.upsert_entity(&target).unwrap();
        let stable_root = state.graph.compute_root_hash();
        let stable_root_hex = hex::encode(stable_root);

        // Initialize a complete spine at the same semantic root. Every hook
        // below inserts and removes a transient entity after the root stamp,
        // returning the graph to this exact root. Root-only validation would
        // accept the first attempt; the monotonic HEAD version must force one
        // retry while each handler reads its detached snapshot.
        let spine = state.ensure_spine().expect("spine enabled in test");
        assert_eq!(
            spine.root_hash(&provider_repo_id).as_deref(),
            Some(stable_root_hex.as_str())
        );
        assert!(
            spine.cross_repo_edges_snapshot().complete,
            "stable primary initialization must publish complete local spine authority"
        );

        let command_attempts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let command_hook_state = Arc::clone(&state);
        let command_hook_attempts = Arc::clone(&command_attempts);
        let command_transient = test_entity("command_transient", "src/transient.rs");
        let command = command_xref_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &kin_cli::commands::xref::XrefRequest {
                entity: target.name.clone(),
            },
            move |attempt| {
                command_hook_attempts.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                if attempt == 0 {
                    command_hook_state
                        .graph
                        .upsert_entity(&command_transient)
                        .unwrap();
                    command_hook_state
                        .graph
                        .remove_entity(&command_transient.id)
                        .unwrap();
                    command_hook_state.bump_version();
                }
            },
        )
        .await
        .expect("command xref retries onto stable authority");
        assert_eq!(
            command_attempts.load(std::sync::atomic::Ordering::SeqCst),
            2
        );
        assert_eq!(state.graph.compute_root_hash(), stable_root);
        assert!(command
            .spine
            .as_ref()
            .is_some_and(|body| body.authority_complete_for(&provider_repo_id, &target.id)));

        let arguments = serde_json::from_value::<HashMap<String, serde_json::Value>>(json!({
            "entity_id": target.id.to_string(),
        }))
        .unwrap();
        let find_attempts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let find_hook_state = Arc::clone(&state);
        let find_hook_attempts = Arc::clone(&find_attempts);
        let find_transient = test_entity("find_transient", "src/transient.rs");
        let find = mcp_find_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &arguments,
            move |attempt| {
                find_hook_attempts.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                if attempt == 0 {
                    find_hook_state
                        .graph
                        .upsert_entity(&find_transient)
                        .unwrap();
                    find_hook_state
                        .graph
                        .remove_entity(&find_transient.id)
                        .unwrap();
                    find_hook_state.bump_version();
                }
            },
        )
        .await
        .expect("find_references retries onto stable authority");
        assert_eq!(find_attempts.load(std::sync::atomic::Ordering::SeqCst), 2);
        let find_body: serde_json::Value = serde_json::from_str(&mcp_result_text(&find)).unwrap();
        assert_eq!(find_body["cross_repo"]["status"], "available");
        assert_eq!(find_body["cross_repo"]["authority_complete"], true);

        let arguments = serde_json::from_value::<HashMap<String, serde_json::Value>>(json!({
            "entity_ids": [target.id.to_string()],
            "relation_kind": "Any",
        }))
        .unwrap();
        let bulk_attempts = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let bulk_hook_state = Arc::clone(&state);
        let bulk_hook_attempts = Arc::clone(&bulk_attempts);
        let bulk_transient = test_entity("bulk_transient", "src/transient.rs");
        let bulk = mcp_bulk_check_references_with_stable_authority(
            &state,
            None,
            Arc::clone(&state.graph),
            RequestGraphAuthority::Head,
            &arguments,
            move |attempt| {
                bulk_hook_attempts.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                if attempt == 0 {
                    bulk_hook_state
                        .graph
                        .upsert_entity(&bulk_transient)
                        .unwrap();
                    bulk_hook_state
                        .graph
                        .remove_entity(&bulk_transient.id)
                        .unwrap();
                    bulk_hook_state.bump_version();
                }
            },
        )
        .await
        .expect("bulk_check_references retries onto stable authority");
        assert_eq!(bulk_attempts.load(std::sync::atomic::Ordering::SeqCst), 2);
        let bulk_body: serde_json::Value = serde_json::from_str(&mcp_result_text(&bulk)).unwrap();
        assert_eq!(bulk_body["cross_repo"]["status"], "available");
        assert_eq!(bulk_body["cross_repo"]["authority_complete"], true);
        assert_eq!(state.graph.compute_root_hash(), stable_root);
    }

    #[test]
    fn mutation_wrapper_blocks_xref_during_stalled_head_and_session_batches() {
        let state = test_state();
        let head_target = test_entity("head_target", "src/head.rs");
        state.graph.upsert_entity(&head_target).unwrap();

        let head_started = Arc::new(std::sync::Barrier::new(2));
        let head_release = Arc::new(std::sync::Barrier::new(2));
        let head_state = Arc::clone(&state);
        let head_started_worker = Arc::clone(&head_started);
        let head_release_worker = Arc::clone(&head_release);
        let head_writer = std::thread::spawn(move || {
            with_graph_authority_mutation(head_state.as_ref(), || {
                let transient = test_entity("head_mid_batch", "src/transient.rs");
                head_state.graph.upsert_entity(&transient).unwrap();
                head_started_worker.wait();
                head_release_worker.wait();
                head_state.graph.remove_entity(&transient.id).unwrap();
                head_state.bump_version();
            });
        });

        head_started.wait();
        assert!(
            prepare_xref_graph_read(&state, &state.graph, RequestGraphAuthority::Head).is_none(),
            "HEAD must not detach an intermediate graph while a writer is stalled"
        );
        head_release.wait();
        head_writer.join().unwrap();
        assert!(
            prepare_xref_graph_read(&state, &state.graph, RequestGraphAuthority::Head).is_some()
        );

        let scoped_graph = Arc::new(kin_db::InMemoryGraph::new());
        let scoped_target = test_entity("scoped_target", "src/scoped.rs");
        scoped_graph.upsert_entity(&scoped_target).unwrap();
        let scope_started = Arc::new(std::sync::Barrier::new(2));
        let scope_release = Arc::new(std::sync::Barrier::new(2));
        let scope_state = Arc::clone(&state);
        let scope_graph_worker = Arc::clone(&scoped_graph);
        let scope_started_worker = Arc::clone(&scope_started);
        let scope_release_worker = Arc::clone(&scope_release);
        let scope_writer = std::thread::spawn(move || {
            with_graph_authority_mutation(scope_state.as_ref(), || {
                let transient = test_entity("scope_mid_batch", "src/transient.rs");
                scope_graph_worker.upsert_entity(&transient).unwrap();
                scope_started_worker.wait();
                scope_release_worker.wait();
                scope_graph_worker.remove_entity(&transient.id).unwrap();
            });
        });

        scope_started.wait();
        assert!(
            prepare_xref_graph_read(&state, &scoped_graph, RequestGraphAuthority::SessionScope,)
                .is_none(),
            "session scope must not detach an intermediate graph mutation"
        );
        scope_release.wait();
        scope_writer.join().unwrap();
        assert!(prepare_xref_graph_read(
            &state,
            &scoped_graph,
            RequestGraphAuthority::SessionScope,
        )
        .is_some());
    }

    #[tokio::test]
    async fn scoped_xref_fails_closed_when_selected_scope_is_replaced_mid_read() {
        let state = test_state();
        let scoped_graph = Arc::new(kin_db::InMemoryGraph::new());
        let target = test_entity("historical_target", "src/lib.rs");
        scoped_graph.upsert_entity(&target).unwrap();
        let session_id = SessionId::new();
        state
            .set_session_scope(
                &session_id,
                "git:historical".to_string(),
                kin_model::SemanticChangeId::from_hash(kin_model::Hash256::from_bytes([7; 32])),
                Arc::clone(&scoped_graph),
            )
            .await;

        let hook_state = Arc::clone(&state);
        let error = command_xref_with_stable_authority(
            &state,
            Some(&session_id),
            scoped_graph,
            RequestGraphAuthority::SessionScope,
            &kin_cli::commands::xref::XrefRequest {
                entity: target.name,
            },
            move |attempt| {
                if attempt == 0 {
                    hook_state
                        .session_scopes
                        .try_write()
                        .expect("xref does not hold the session scope lock")
                        .remove(&session_id);
                }
            },
        )
        .await
        .expect_err("an orphaned session graph must never be certified");
        assert_eq!(error.0, StatusCode::SERVICE_UNAVAILABLE);
        assert!(error.1.contains("changed repeatedly"));
    }

    /// Fail-loud contract: when a spine endpoint IS configured but the daemon
    /// answers non-2xx (e.g. `503` because the spine is disabled), every client
    /// surface must report the gap as `SpineQuery::Unavailable` — never collapse
    /// it into a silent empty result (the old `Ok(None)` swallow) nor a quiet
    /// `NotConfigured`. This is the cross-repo analogue of the graph-first
    /// "fail loud or report the gap" rule, enforced across CLI and MCP.
    #[tokio::test]
    #[serial_test::serial]
    async fn spine_clients_surface_unavailable_on_non_success_status() {
        use kin_cli::backend::{get_spine_impact, get_spine_xref};
        use kin_mcp::handlers::common::{fetch_spine_impact_typed, fetch_spine_xref};

        // A stand-in daemon that answers every route 503. No real graph and no
        // autostart — the clients reach it purely through KIN_DAEMON_URL.
        async fn always_unavailable() -> StatusCode {
            StatusCode::SERVICE_UNAVAILABLE
        }
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, Router::new().fallback(always_unavailable)).await;
        });
        let _daemon_url =
            kin_core::test_env::EnvVarGuard::set("KIN_DAEMON_URL", format!("http://{addr}"));

        let layout = test_state().layout.clone();
        let repo = "consumer";
        let entity = EntityId::new();

        // ── CLI xref: configured-but-failing must be Unavailable, naming 503. ──
        match get_spine_xref(&layout, repo, &entity)
            .await
            .expect("CLI get_spine_xref call")
        {
            kin_spine::SpineQuery::Unavailable(reason) => {
                assert!(
                    reason.contains("503"),
                    "reason must name the status: {reason}"
                );
            }
            other => panic!("CLI xref must be Unavailable on 503, got {other:?}"),
        }

        // ── CLI impact: the surface migrated off the Ok(None) swallow. ──
        match get_spine_impact(&layout, repo, &entity, 5)
            .await
            .expect("CLI get_spine_impact call")
        {
            kin_spine::SpineQuery::Unavailable(reason) => {
                assert!(
                    reason.contains("503"),
                    "reason must name the status: {reason}"
                );
            }
            other => panic!("CLI impact must be Unavailable on 503, got {other:?}"),
        }

        // ── MCP xref + impact: same fail-loud contract. ──
        match fetch_spine_xref(repo, &entity).await {
            kin_spine::SpineQuery::Unavailable(_) => {}
            other => panic!("MCP xref must be Unavailable on 503, got {other:?}"),
        }
        match fetch_spine_impact_typed(repo, &entity, 5).await {
            kin_spine::SpineQuery::Unavailable(_) => {}
            other => panic!("MCP impact must be Unavailable on 503, got {other:?}"),
        }

        server.abort();
    }

    /// Names its repository and spine endpoint by argument on purpose. An
    /// earlier version set `KIN_REPO_ID` and `KIN_DAEMON_URL`, which are
    /// process-global, and under `cargo test` this binary's ~600 tests are
    /// threads in one process, so every test that opened a daemon state while
    /// this one held `KIN_REPO_ID=provider` was refused against its own
    /// manifest authority. `#[serial]` cannot prevent that: it orders a test
    /// only against other serial tests. Under nextest, which gives each test
    /// its own process, the defect is structurally invisible.
    #[tokio::test]
    async fn mcp_find_references_reports_legacy_xref_payload_as_unavailable() {
        async fn legacy_xref() -> Json<serde_json::Value> {
            Json(serde_json::json!({
                "version": kin_spine::SPINE_PAYLOAD_VERSION,
                "edges": [{
                    "repo_id": "consumer",
                    "from_name": "run_task",
                    "to_repo_id": "provider",
                    "kind": "calls",
                }],
            }))
        }

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, Router::new().fallback(legacy_xref)).await;
        });
        let binding = kin_mcp::handlers::entities::AmbientCrossRepoBinding::new(
            Some("provider"),
            Some(&format!("http://{addr}")),
        );

        let target = test_entity("do_work", "src/lib.rs");
        let graph = kin_db::InMemoryGraph::new();
        graph.upsert_entity(&target).unwrap();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(target.id.to_string()),
        )]);
        let result = kin_mcp::handlers::entities::handle_find_references_with_ambient_binding(
            &args, &graph, binding, None,
        )
        .await
        .unwrap();
        let kin_mcp::types::ContentBlock::Text { text } = result
            .content
            .first()
            .expect("find_references text response");
        let body: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(body["cross_repo"]["status"], "unavailable");
        assert!(body["cross_repo"]["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("malformed spine xref response")));
        assert_eq!(body["total_upstream"], 0);

        server.abort();
    }

    /// Names its binding by argument for the reason given on
    /// `mcp_find_references_reports_legacy_xref_payload_as_unavailable`.
    #[tokio::test]
    async fn mcp_find_references_rejects_unanchored_xref_as_inconclusive() {
        async fn legacy_xref() -> Json<serde_json::Value> {
            Json(serde_json::json!({
                "version": kin_spine::SPINE_PAYLOAD_VERSION,
                "edges": [],
            }))
        }

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, Router::new().fallback(legacy_xref)).await;
        });
        let binding = kin_mcp::handlers::entities::AmbientCrossRepoBinding::new(
            Some("provider"),
            Some(&format!("http://{addr}")),
        );

        let target = test_entity("do_work", "src/lib.rs");
        let graph = kin_db::InMemoryGraph::new();
        graph.upsert_entity(&target).unwrap();
        let args = HashMap::from([(
            "entity_id".to_string(),
            serde_json::json!(target.id.to_string()),
        )]);
        let result = kin_mcp::handlers::entities::handle_find_references_with_ambient_binding(
            &args, &graph, binding, None,
        )
        .await
        .unwrap();
        let result = kin_mcp::finalize_with_envelope(
            result,
            kin_mcp::Envelope::daemon().with_health(&serde_json::json!({
                "initialized": true,
                "graph_loaded": true,
                "graph_generation": 12,
            })),
            "find_references",
        );
        let kin_mcp::types::ContentBlock::Text { text } = result
            .content
            .first()
            .expect("find_references text response");
        let body: serde_json::Value = serde_json::from_str(text).unwrap();
        assert_eq!(body["cross_repo"]["status"], "unavailable");
        assert!(body["cross_repo"]["reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("xref response anchor does not match")));
        assert_eq!(body["negative"]["safe_to_conclude_absent"], false);
        assert!(body["negative"]["trust_reason"]
            .as_str()
            .is_some_and(|reason| reason.contains("cross_repo_unavailable")));

        server.abort();
    }

